  1	import { Suspense } from "react";
  2	import { HomeFlow } from "./HomeFlow";
  3	
  4	export default function HomePage() {
  5	  return (
  6	    <Suspense>
  7	      <HomeFlow />
  8	    </Suspense>
  9	  );
 10	}
  1	"use client";
  2	
  3	import { useEffect, useState } from "react";
  4	import { useRouter, useSearchParams } from "next/navigation";
  5	import type { CreateSessionResponse, UnlockResponse, UserView } from "@/lib/contracts/api";
  6	import type { Intent, SessionSummary } from "@/lib/contracts/session";
  7	import { UNLOCK_PHRASE } from "@/lib/contracts/api";
  8	import { IntentFlow } from "@/components/IntentFlow";
  9	import { LimitsBanner } from "@/components/LimitsBanner";
 10	import { Pip } from "@/components/Pip";
 11	import { useSounds } from "@/components/SoundProvider";
 12	import { UiProviders } from "@/components/UiProviders";
 13	import { Button, Spinner } from "@/components/ui";
 14	import { ApiError, apiGet, apiPost, errorMessage } from "@/lib/client/api";
 15	import { rememberTheme } from "@/lib/ui/themeBoot";
 16	import { startOverAsNewUser } from "@/lib/client/reset";
 17	
 18	type Stage = "checking" | "unlock" | "home" | "intent";
 19	
 20	/**
 21	 * `/`: the /co-learn unlock ritual → continue a past session or start one (intent) → the workspace.
 22	 * Keyed by bfcacheId: Next keeps visited routes mounted (Activity), so a fresh push/replace (e.g. "Start a new
 23	 * session" from a wrap-up) must start over instead of showing the last visit's half-finished intent form.
 24	 */
 25	export function HomeFlow() {
 26	  const { bfcacheId } = useRouter();
 27	  return <HomeFlowInner key={bfcacheId} />;
 28	}
 29	
 30	function HomeFlowInner() {
 31	  const params = useSearchParams();
 32	  const startDirectly = params.get("start") === "1";
 33	  const initialGoal = params.get("goal") ?? "";
 34	  const [stage, setStage] = useState<Stage>(startDirectly ? "checking" : "unlock");
 35	  const [user, setUser] = useState<UserView | null>(null);
 36	  const [sessions, setSessions] = useState<SessionSummary[]>([]);
 37	
 38	  // "Start a new session" from a wrap-up skips the ritual when the browser is already unlocked.
 39	  useEffect(() => {
 40	    if (!startDirectly) return;
 41	    apiGet<UserView>("/api/user")
 42	      .then((u) => {
 43	        setUser(u);
 44	        setStage("intent");
 45	      })
 46	      .catch(() => setStage("unlock"));
 47	  }, [startDirectly]);
 48	
 49	  useEffect(() => {
 50	    if (user) rememberTheme(user.settings.theme);
 51	  }, [user]);
 52	
 53	  const s = user?.settings;
 54	  return (
 55	    <UiProviders theme={s?.theme} sound={s ? { enabled: s.sound, volume: s.volume, pack: s.soundPack } : undefined}>
 56	      <LimitsBanner />
 57	      <main className="flex flex-1 flex-col items-center justify-center gap-6 px-6 py-12">
 58	        {stage === "checking" && <Spinner label="Loading" />}
 59	        {stage === "unlock" && (
 60	          <UnlockBox
 61	            onUnlocked={(res) => {
 62	              setUser(res.user);
 63	              setSessions(res.sessions);
 64	              setStage(res.sessions.length ? "home" : "intent");
 65	            }}
 66	          />
 67	        )}
 68	        {stage === "home" && (
 69	          <Welcome
 70	            sessions={sessions}
 71	            onNew={() => setStage("intent")}
 72	            onStartOver={async () => {
 73	              const fresh = await startOverAsNewUser();
 74	              setUser(fresh);
 75	              setSessions([]);
 76	              setStage("intent");
 77	            }}
 78	          />
 79	        )}
 80	        {stage === "intent" && <Intent initialGoal={initialGoal} />}
 81	      </main>
 82	    </UiProviders>
 83	  );
 84	}
 85	
 86	function UnlockBox({ onUnlocked }: { onUnlocked: (res: UnlockResponse) => void }) {
 87	  const [value, setValue] = useState("");
 88	  const [state, setState] = useState<"idle" | "checking" | "unlocked" | "wrong" | "error">("idle");
 89	  const [error, setError] = useState<string | null>(null);
 90	  const sounds = useSounds();
 91	
 92	  async function submit(e: React.FormEvent) {
 93	    e.preventDefault();
 94	    if (value.trim().toLowerCase() !== UNLOCK_PHRASE) {
 95	      setState("wrong");
 96	      sounds.play("gentle");
 97	      return;
 98	    }
 99	    setState("checking");
100	    try {
101	      const res = await apiPost<UnlockResponse>("/api/unlock", { phrase: value.trim() });
102	      setState("unlocked");
103	      sounds.play("unlock");
104	      // A beat to enjoy the "box opens" moment before moving on.
105	      setTimeout(() => onUnlocked(res), 900);
106	    } catch (err) {
107	      setError(errorMessage(err));
108	      setState("error");
109	    }
110	  }
111	
112	  return (
113	    <>
114	      <Pip mood={state === "unlocked" ? "celebrating" : state === "wrong" || state === "error" ? "encouraging" : "neutral"} />
115	      <form onSubmit={submit} className="w-full max-w-md">
116	        <label htmlFor="unlock" className="sr-only">Type /co-learn to begin</label>
117	        <input
118	          id="unlock"
119	          autoFocus
120	          autoComplete="off"
121	          spellCheck={false}
122	          value={value}
123	          onChange={(e) => { setValue(e.target.value); if (state === "wrong" || state === "error") setState("idle"); }}
124	          placeholder={UNLOCK_PHRASE}
125	          disabled={state === "checking" || state === "unlocked"}
126	          className={`w-full rounded-full border bg-surface px-6 py-4 text-center text-lg shadow-soft outline-none transition focus:border-primary focus:ring-4 focus:ring-primary-soft ${state === "unlocked" ? "scale-105 border-primary" : "border-border"}`}
127	        />
128	      </form>
129	      <p className="text-sm text-muted" aria-live="polite">
130	        {state === "unlocked"
131	          ? "Co-learn mode is on."
132	          : state === "wrong"
133	            ? "Almost: type /co-learn to switch on Co-learn mode."
134	            : state === "error"
135	              ? error
136	              : "Type /co-learn to switch on Co-learn mode."}
137	      </p>
138	    </>
139	  );
140	}
141	
142	function Welcome({ sessions, onNew, onStartOver }: { sessions: SessionSummary[]; onNew: () => void; onStartOver: () => Promise<void> }) {
143	  const [confirm, setConfirm] = useState(false);
144	  const [error, setError] = useState<string | null>(null);
145	  const router = useRouter();
146	  const recent = [...sessions].sort((a, b) => b.createdAt - a.createdAt).slice(0, 3);
147	  return (
148	    <div className="flex w-full max-w-md flex-col items-center gap-5 text-center">
149	      <Pip mood="happy" />
150	      <p className="text-xl font-bold">Welcome back!</p>
151	      <div className="flex w-full flex-col gap-2">
152	        {recent.map((s) => (
153	          <Button key={s.id} onClick={() => router.push(`/s/${s.id}`)} className="w-full justify-between">
154	            <span className="truncate">{s.status === "wrapped" ? "Revisit" : "Continue"}: {s.title}</span>
155	            <span className="shrink-0 text-xs font-normal text-muted">{shortDate(s.createdAt)}</span>
156	          </Button>
157	        ))}
158	      </div>
159	      <Button variant="primary" onClick={onNew}>Start something new</Button>
160	      {confirm ? (
161	        <div className="flex flex-col items-center gap-2 rounded-2xl bg-surface-2 p-3 text-sm">
162	          <p>Start over as a brand-new user? Your XP, unlocks, and past sessions on this browser will be gone.</p>
163	          <div className="flex gap-2">
164	            <Button size="sm" variant="primary" onClick={() => onStartOver().catch((err) => setError(errorMessage(err)))}>Yes, start over</Button>
165	            <Button size="sm" onClick={() => setConfirm(false)}>Cancel</Button>
166	          </div>
167	          {error && <p role="alert" className="text-muted">{error}</p>}
168	        </div>
169	      ) : (
170	        <Button size="sm" variant="quiet" onClick={() => setConfirm(true)}>Start over as a new user</Button>
171	      )}
172	    </div>
173	  );
174	}
175	
176	const shortDate = (at: number) => new Date(at).toLocaleString(undefined, { month: "short", day: "numeric", hour: "numeric", minute: "2-digit" });
177	
178	function Intent({ initialGoal }: { initialGoal: string }) {
179	  const router = useRouter();
180	  const [busy, setBusy] = useState(false);
181	  const [error, setError] = useState<string | null>(null);
182	
183	  async function start(intent: Intent) {
184	    setBusy(true);
185	    setError(null);
186	    try {
187	      const { sessionId } = await apiPost<CreateSessionResponse>("/api/session", { intent });
188	      router.push(`/s/${sessionId}`);
189	    } catch (err) {
190	      setError(err instanceof ApiError && err.status === 401 ? "Your Co-learn session expired. Reload and type /co-learn again." : errorMessage(err));
191	      setBusy(false);
192	    }
193	  }
194	
195	  return (
196	    <div className="flex w-full flex-col items-center gap-4">
197	      <IntentFlow onComplete={start} busy={busy} initialGoal={initialGoal} />
198	      {error && <p role="alert" className="text-sm text-muted">{error}</p>}
199	    </div>
200	  );
201	}
  1	import { ensureAnonId } from "@/lib/platform/anon";
  2	import { jsonError, routeErrorResponse } from "@/lib/platform/http";
  3	import { getStore } from "@/lib/store";
  4	import { newUser } from "@/lib/store/defaults";
  5	import { UNLOCK_PHRASE, type UnlockRequest, type UnlockResponse } from "@/lib/contracts/api";
  6	import { toUserView } from "@/lib/views";
  7	
  8	export async function POST(request: Request) {
  9	  const body = (await request.json().catch(() => null)) as UnlockRequest | null;
 10	  if (body?.phrase?.trim().toLowerCase() !== UNLOCK_PHRASE) {
 11	    return jsonError(400, "Type /co-learn to switch on Co-learn mode.", "bad_phrase");
 12	  }
 13	  try {
 14	    const anonId = await ensureAnonId();
 15	    const store = getStore();
 16	    let user = await store.getUser(anonId);
 17	    if (!user) {
 18	      user = newUser(anonId);
 19	      await store.putUser(user);
 20	    }
 21	    await store.logEvent({ at: Date.now(), anonId, name: "unlock" });
 22	    const res: UnlockResponse = { ok: true, user: toUserView(user), sessions: await store.listSessions(anonId) };
 23	    return Response.json(res);
 24	  } catch (err) {
 25	    return routeErrorResponse(err, "POST /api/unlock");
 26	  }
 27	}

