  1	/**
  2	 * Core entities persisted per user/session. See docs/design-plan.md §10.
  3	 */
  4	import type Anthropic from "@anthropic-ai/sdk";
  5	import type { EngineState, Familiarity, UserSettings, BossOutcome } from "./engine";
  6	import type { HelpLevel, LearningMomentInput, MomentHelpView, MomentStatus, MomentType, Verdict } from "./moment";
  7	
  8	export interface User {
  9	  anonId: string;
 10	  createdAt: number;
 11	  xp: number;
 12	  level: number;
 13	  unlocks: { themes: string[]; soundPacks: string[] };
 14	  settings: UserSettings;
 15	}
 16	
 17	export interface Intent {
 18	  goal: string;
 19	  familiarity: Familiarity;
 20	  minutes: number; // session length target (default 10)
 21	  demo: boolean; // started from the churn demo starter
 22	}
 23	
 24	/** Light "session sketch" generated in the background (Opus, high effort). Not a curriculum. */
 25	export interface SessionSketch {
 26	  title: string;
 27	  goalSummary: string;
 28	  novice: boolean;
 29	  milestones: string[]; // 3-5 likely chunks of work
 30	  conceptRadar: { concept: string; whyItMatters: string; likelyMomentType: MomentType }[];
 31	}
 32	
 33	export interface StoryBible {
 34	  genre: string;
 35	  tone: string;
 36	  setting: string;
 37	  protagonist: string;
 38	  motif: string; // light theming drawn from the user's work
 39	  arc: string[]; // planned beats
 40	  seeds: { narrator: string; twist: string };
 41	}
 42	
 43	/** A 60-second primer: a few key ideas plus one warm-up check (decision log 2026-10-18). Server-side record. */
 44	export interface Primer {
 45	  ideas: string[]; // 3-4 short markdown lines
 46	  check: { question: string; options: string[]; correctIndex: number; why: string[] };
 47	  createdAt: number;
 48	  dismissed?: boolean;
 49	  answer?: { choice: number; correct: boolean };
 50	}
 51	
 52	export interface StoryChapter {
 53	  id: string;
 54	  trigger: string; // e.g. "boss:<id>" | "wrapup"
 55	  title: string;
 56	  text: string;
 57	  summary: string;
 58	  createdAt: number;
 59	}
 60	
 61	export interface StoryState {
