     1	/** Session creation and background enrichment (sketch, story bible when the mode has a story, primer). */
     2	import { z } from "zod";
     3	import type { CreateSessionResponse } from "@/lib/contracts/api";
     4	import { initialEngineState } from "@/lib/contracts/engine";
     5	import type { Intent, Session } from "@/lib/contracts/session";
     6	import { MODES } from "@/lib/modes";
     7	import type { HandlerResult, LearningDeps } from "./deps";
     8	import { patchSession } from "./sessionStore";
     9	
    10	export const IntentSchema = z.object({
    11	  goal: z.string().trim().min(1, "Tell us what you're working on").max(2000),
    12	  familiarity: z.enum(["new", "some", "comfortable"]),
    13	  minutes: z.number().int().min(5).max(120).default(10),
    14	  demo: z.boolean().default(false),
    15	});
    16	export const CreateSessionRequestSchema = z.object({ intent: IntentSchema });
    17	
    18	/** A provisional title from the goal (≤ 40 chars, cut at a word boundary); the sketch replaces it later. */
    19	export function titleFromGoal(goal: string, max = 40): string {
    20	  const clean = goal.replace(/\s+/g, " ").trim();
    21	  if (clean.length <= max) return clean;
    22	  const cut = clean.slice(0, max - 1);
    23	  const atWord = cut.lastIndexOf(" ");
    24	  return `${(atWord > max / 2 ? cut.slice(0, atWord) : cut).replace(/[\s.,;:!?-]+$/, "")}…`;
    25	}
    26	
    27	export async function createSession(deps: LearningDeps, anonId: string, intent: Intent): Promise<HandlerResult<CreateSessionResponse>> {
    28	  const now = deps.now();
    29	  const session: Session = {
    30	    id: deps.newId(),
    31	    anonId,
    32	    createdAt: now,
    33	    title: titleFromGoal(intent.goal),
    34	    intent,
    35	    fileIds: [],
    36	    demoFileAttached: false,
    37	    status: "active",
    38	    engine: initialEngineState(),
    39	    story: { enabled: MODES["co-learn"].story, chapters: [] },
    40	  };
    41	  await deps.store.putSession(session);
    42	  await deps.store.putTranscript(session.id, []);
    43	  await deps.store.logEvent({ at: now, anonId, sessionId: session.id, name: "session_created", props: { demo: intent.demo, familiarity: intent.familiarity, minutes: intent.minutes } });
    44	  return { body: { sessionId: session.id }, background: [() => enrichSession(deps, session.id)] };
    45	}
    46	
    47	/**
    48	 * Generates the sketch and story bible in parallel, then patches only `sketch`, `title`, and
    49	 * `story.bible` onto the latest session (the work loop writes engine/containerId/fileIds concurrently).
    50	 */
    51	export async function enrichSession(deps: LearningDeps, sessionId: string): Promise<void> {
    52	  const session = await deps.store.getSession(sessionId);
    53	  if (!session) return;
    54	  // The primer is the fastest call and is meant to appear during the first work turn, so it saves on its own.
    55	  const primerTask =
    56	    session.intent.familiarity === "new" && !session.primer
    57	      ? deps.content.generatePrimer({ intent: session.intent }).then((draft) =>
    58	          patchSession(deps, sessionId, (latest) => ({ primer: latest.primer ?? { ...draft, createdAt: deps.now() } })),
    59	        )
    60	      : Promise.resolve(null);
    61	  const [sketch, bible, primer] = await Promise.allSettled([
    62	    deps.content.generateSketch({ intent: session.intent }),
    63	    !session.story.enabled || session.story.bible ? Promise.resolve(session.story.bible) : deps.content.generateStoryBible({ intent: session.intent }),
    64	    primerTask,
    65	  ]);
    66	  await patchSession(deps, sessionId, (latest) => ({
    67	    ...(sketch.status === "fulfilled" ? { sketch: sketch.value, title: sketch.value.title || latest.title } : {}),
    68	    story: { ...latest.story, bible: latest.story.bible ?? (bible.status === "fulfilled" ? bible.value : undefined) },
    69	  }));
    70	  for (const r of [sketch, bible, primer]) {
    71	    if (r.status === "rejected") {
    72	      await deps.store.logEvent({ at: deps.now(), anonId: session.anonId, sessionId, name: "error", props: { where: "enrichSession", message: String(r.reason).slice(0, 200) } });
    73	    }
    74	  }
    75	}
