  1	"use client";
  2	
  3	import { useId, useState } from "react";
  4	import type { Familiarity } from "@/lib/contracts/engine";
  5	import type { Intent } from "@/lib/contracts/session";
  6	import { Pip } from "./Pip";
  7	import { useSounds } from "./SoundProvider";
  8	import { Button, Chip, focusRing } from "./ui";
  9	
 10	export const DEMO_GOAL = "Help me train a model to predict customer churn from this CSV.";
 11	
 12	const FAMILIARITY: { id: Familiarity; label: string }[] = [
 13	  { id: "new", label: "New to this" },
 14	  { id: "some", label: "Some experience" },
 15	  { id: "comfortable", label: "Comfortable" },
 16	];
 17	const MINUTES = [10, 20, 30] as const;
 18	
 19	export interface IntentFlowProps {
 20	  onComplete: (intent: Intent) => void;
 21	  /** Disable the final button while the session is being created. */
 22	  busy?: boolean;
 23	  autoFocus?: boolean;
 24	  /** Prefills the goal (e.g. a "Next time you could…" suggestion from a wrap-up). */
 25	  initialGoal?: string;
 26	}
 27	
 28	/** Intent step: goal (or the demo starter), then familiarity + time chips. */
 29	export function IntentFlow({ onComplete, busy = false, autoFocus = true, initialGoal = "" }: IntentFlowProps) {
 30	  const [step, setStep] = useState<"goal" | "details">("goal");
 31	  const [goal, setGoal] = useState(initialGoal);
 32	  const [demo, setDemo] = useState(initialGoal.trim() === DEMO_GOAL);
 33	  const [familiarity, setFamiliarity] = useState<Familiarity | null>(null);
 34	  const [minutes, setMinutes] = useState<number>(10);
 35	  const sounds = useSounds();
 36	  const goalId = useId();
 37	  const famLabel = useId();
 38	  const timeLabel = useId();
 39	
 40	  function next() {
 41	    if (!goal.trim()) return;
 42	    setStep("details");
 43	  }
 44	
 45	  function startDemo() {
 46	    sounds.play("click");
 47	    setGoal(DEMO_GOAL);
 48	    setDemo(true);
 49	    setStep("details");
 50	  }
 51	
 52	  function finish() {
 53	    if (!familiarity || busy) return;
 54	    onComplete({ goal: goal.trim(), familiarity, minutes, demo: demo && goal.trim() === DEMO_GOAL });
 55	  }
 56	
 57	  if (step === "goal") {
 58	    return (
 59	      <div className="mx-auto flex w-full max-w-xl flex-col items-center gap-5">
 60	        <Pip mood="happy" />
 61	        <label htmlFor={goalId} className="text-center text-xl font-bold">What are you working on?</label>
 62	        <textarea
 63	          id={goalId}
 64	          autoFocus={autoFocus}
 65	          rows={3}
 66	          value={goal}
 67	          maxLength={1000}
 68	          placeholder="e.g. Analyze our signup funnel in SQL, or draft a project plan…"
 69	          onChange={(e) => { setGoal(e.target.value); setDemo(e.target.value.trim() === DEMO_GOAL); }}
 70	          onKeyDown={(e) => {
 71	            if (e.key === "Enter" && !e.shiftKey && !e.nativeEvent.isComposing) { e.preventDefault(); next(); }
 72	          }}
 73	          className="w-full resize-none rounded-card border border-border bg-surface p-4 leading-relaxed shadow-soft outline-none placeholder:text-muted focus:border-primary"
 74	        />
 75	        <div className="flex w-full flex-wrap items-center justify-center gap-3">
 76	          <button
 77	            type="button"
 78	            onClick={startDemo}
 79	            className={`rounded-full bg-primary px-5 py-2.5 font-semibold text-primary-foreground shadow-soft transition hover:brightness-110 ${focusRing}`}
 80	          >
 81	            <span aria-hidden="true">▶ </span>Try the demo: train a churn model
 82	          </button>
 83	          <Button onClick={next} disabled={!goal.trim()}>Next</Button>
 84	        </div>
 85	      </div>
 86	    );
 87	  }
 88	
 89	  return (
 90	    <div className="mx-auto flex w-full max-w-xl flex-col items-center gap-6">
 91	      <Pip mood="neutral" />
 92	      <div className="w-full rounded-card bg-surface-2 px-4 py-3 text-sm">
 93	        <span className="font-bold text-muted">Working on: </span>
 94	        <span>{goal.trim()}</span>{" "}
 95	        <button type="button" onClick={() => setStep("goal")} className={`rounded font-semibold text-primary underline underline-offset-2 ${focusRing}`}>
 96	          Change
 97	        </button>
 98	      </div>
 99	
100	      <div className="flex w-full flex-col items-center gap-3">
101	        <p id={famLabel} className="text-lg font-bold">How familiar are you with this?</p>
102	        <div role="group" aria-labelledby={famLabel} className="flex flex-wrap justify-center gap-2">
103	          {FAMILIARITY.map((f) => (
104	            <Chip key={f.id} selected={familiarity === f.id} onClick={() => { sounds.play("click"); setFamiliarity(f.id); }}>
105	              {f.label}
106	            </Chip>
107	          ))}
108	        </div>
109	      </div>
110	
111	      <div className="flex w-full flex-col items-center gap-3">
112	        <p id={timeLabel} className="text-lg font-bold">How long do you have?</p>
113	        <div role="group" aria-labelledby={timeLabel} className="flex flex-wrap justify-center gap-2">
114	          {MINUTES.map((n) => (
115	            <Chip key={n} selected={minutes === n} onClick={() => { sounds.play("click"); setMinutes(n); }}>
116	              {n} min
117	            </Chip>
118	          ))}
119	        </div>
120	      </div>
121	
122	      <Button variant="primary" onClick={finish} disabled={!familiarity || busy}>
123	        {busy ? "Starting…" : "Let's go"}
124	      </Button>
125	    </div>
126	  );
127	}

