10	export const SketchOutputSchema = z.object({
11	  title: z.string().describe("Short session title, at most 40 characters, no quotes"),
12	  goal_summary: z.string().describe("One sentence restating what the learner wants to get done"),
13	  novice: z.boolean().describe("True if the learner seems new to this area"),
14	  milestones: z.array(z.string()).describe("3-5 likely chunks of work, each a short phrase"),
15	  concept_radar: z
16	    .array(
17	      z.object({
18	        concept: z.string().describe("Short canonical concept name, lower case, e.g. 'class imbalance'"),
19	        why_it_matters: z.string().describe("One line: why this matters for this learner's goal"),
20	        likely_moment_type: z.enum(MOMENT_TYPES),
21	      }),
22	    )
23	    .describe("5-10 concepts likely to come up, most important first"),
24	});
25	
26	export const SKETCH_SYSTEM = `You plan a short Co-learn session. In Co-learn a professional does real work with Claude, and at high-value moments Claude pauses to turn the work into a quick challenge the learner solves themselves (decide, predict, explain_back, spot_issue, fill_gap).
27	
28	From the learner's goal, familiarity, and time budget, sketch the session lightly. This is not a curriculum: the work will change as it goes.
29	- title: at most 40 characters, specific to their task.
30	- milestones: 3-5 natural chunks of the work that fit the time budget, in order.
31	- concept_radar: 5-10 concepts the work will likely touch where the learner's own judgment matters most for their goal, each with why it matters and the moment type that fits best (decide at real forks, predict before results appear, spot_issue for pitfalls such as data leakage).
32	- novice: true if they are new to this area. Calibrate to their familiarity and how they phrase the goal.
33	${DATA_RULE}`;
34	
35	const familiarityLabel: Record<Intent["familiarity"], string> = {
36	  new: "new to this area",
37	  some: "some experience",
38	  comfortable: "comfortable with this area",
39	};
40	
41	export function sketchPrompt(intent: Intent): string {
42	  return [
43	    asData("learner_goal", truncate(intent.goal, 2000)),
44	    `Familiarity: ${familiarityLabel[intent.familiarity]}`,
45	    `Time budget: about ${intent.minutes} minutes`,
46	    intent.demo ? "Context: the learner started from the demo, training a churn-prediction model on a customer CSV (planted issues: class imbalance, a leaky column, missing values)." : "",
47	  ]
48	    .filter(Boolean)
49	    .join("\n");
50	}
51	
52	export const generateSketch: ContentApi["generateSketch"] = async ({ intent }) => {
53	  const out = await callStructured({ task: "generateSketch", route: MODELS.sketch, system: SKETCH_SYSTEM, user: sketchPrompt(intent), schema: SketchOutputSchema, timeoutMs: 180_000 });
54	  return normalizeSketch(out, intent);
55	};
56	
57	export function normalizeSketch(out: z.infer<typeof SketchOutputSchema>, intent: Intent): SessionSketch {
58	  // Familiarity is the learner's own statement, so it overrides the model at the extremes.
59	  const novice = intent.familiarity === "new" ? true : intent.familiarity === "comfortable" ? false : out.novice;
60	  return {
61	    title: truncate(out.title.trim().replace(/^["']|["']$/g, ""), 40) || truncate(intent.goal, 40),
62	    goalSummary: out.goal_summary.trim(),
63	    novice,
64	    milestones: out.milestones.map((m) => m.trim()).filter(Boolean).slice(0, 5),
65	    conceptRadar: out.concept_radar
66	      .filter((c) => c.concept.trim())
67	      .slice(0, 10)
68	      .map((c) => ({ concept: truncate(c.concept.trim(), 60), whyItMatters: c.why_it_matters.trim(), likelyMomentType: c.likely_moment_type })),
69	  };
70	}
