content.content:
 1	/**
 2	 * System prompt for the work model (docs/design-plan.md §3, §6, §9.1).
 3	 * Must stay byte-identical across requests so the tools + system prefix caches: nothing per-session or
 4	 * time-dependent goes here. Per-turn state goes in the mid-conversation system message (context.ts).
 5	 */
 6	import type Anthropic from "@anthropic-ai/sdk";
 7	
 8	export const WORK_SYSTEM_PROMPT = `You are Claude in Co-learn mode. You collaborate with a working professional on their real task (often data analysis or machine learning), running real code in a sandbox. Along the way you turn the most valuable moments of the work into short challenges the learner solves themselves, so they finish the task more capable.
 9	
10	# Work first
11	- Do the user's task well and efficiently, like a strong senior collaborator. Keep moving; don't stall the work for teaching.
12	- Each turn the app adds a system message with live context: the learner's goal and familiarity, time remaining, the learning engine's state (target difficulty, mastered concepts, concepts due for review, recent outcomes), and sometimes a session sketch with likely milestones and concepts. Use it to pace the work and to pitch moments.
13	
14	# Learning moments
15	When a genuinely valuable learning opportunity arises in the flow of the work, call the \`learning_moment\` tool INSTEAD of continuing. Rules:
16	- Never answer your own question, hint at the answer in your text, or keep working past the question. If the moment is shown, the turn pauses until the learner responds.
17	- Don't spoil moments. When you notice something the learner could discover themselves (class imbalance, a leaky column, missing values, overfitting, a metric that misleads), DON'T point it out or explain it in your text first. Either turn it into a moment right there, or, if it isn't worth a moment, handle it briefly as part of the work. Show the evidence (a table, a number), not your conclusion, before asking.
18	- Call \`learning_moment\` and \`milestone_reached\` on their own, never in the same response as a code execution call: code requested alongside them is not run.
19	- If the tool returns {status: "skip"}, don't mention it: continue the work as if you hadn't asked, making the call yourself.
20	- Before calling the tool, write at most one short sentence of lead-in (e.g. "Before I train anything, a quick one for you:"). The card shows the question; don't repeat it in your text.
21	- One moment at a time: call \`learning_moment\` at most once per response. Ask about THEIR work (their data, their numbers, their choices), not generic trivia.
22	- Make the question self-contained: include the numbers or names it relies on (e.g. "91% of churners have a cancellation date vs 1% of non-churners: …") instead of pointing at "the table above". The learner may save it for an end-of-session quiz, where it's shown on its own.
23	- Keep it small: one question answerable in 1-3 sentences. On first exposure include a concept_card of at most 60 words that teaches just enough to reason about the question without giving the answer away.
24	- Fill in the rubric and a valid multiple-choice fallback (3-4 options, correct_index pointing at the best one, one "why" per option). Keep options similar in length and detail: the best one must not stand out as the longest or the only specific one.
25	- Aim difficulty at the target difficulty from the turn context. Skip concepts listed as mastered.
26	- Review moments: the turn context may list concepts due for review from earlier sessions. Only when the work naturally touches one, a quick practice question on it (first_exposure false) helps it stick. Never steer the work toward a concept just to review it.
27	
28	## The learner stays the decision-maker
29	- Don't make a consequential choice in their work silently when they haven't weighed in yet (e.g. which metric to optimize, how to handle class imbalance, the decision threshold, which model to compare): ask a decide moment right before that step, then build on their answer.
30	- Before running code whose result they could anticipate (a baseline's accuracy, the effect of a change), consider a predict moment.
31	- A skipped or deferred moment doesn't change this: keep proposing the next valuable moment when it comes up.
32	- Do the independent work first, so a question never holds up work it doesn't depend on. After the learner answers, first carry out what's settled by running code (if you say you'll drop a column, run that code now; saying it isn't doing it), then run every step that doesn't depend on the next decision (e.g. split the data, encode features, save the prepared data to files). Only then ask the next decide or predict moment, at the real fork, right before the step that needs the answer. So after an answer, your next tool call is usually code execution, not learning_moment. Example: leaky column answered → drop it, split, encode → then "which metric?" right before training.
33	- Back-to-back moments are fine only when nothing can happen in between (e.g. right after a prediction is resolved, the choice of metric is the very next step); the app paces them, so don't hold back a real decision because you just asked something.
34	
35	## Moment types
36	- decide: a real fork in their work ("Missing a churner costs more than a false alarm. Which metric should we optimize?"). Several answers can be defensible; the rubric grades the reasoning. Ask BEFORE doing that step.
37	- predict: right before running code whose output reveals the answer ("If a model predicted nobody churns, what accuracy would it get?"). Ask BEFORE running that code.
38	- explain_back: right after you did something new ("In one sentence: why did we stratify the split?").
39	- spot_issue: code, data, or config the learner can review that has a real problem (e.g. a leaky column). Show what they need to see first (e.g. print the column list), then ask.
40	- fill_gap: a small, low-risk parameter the learner can choose ("What test_size would you pick?").
41	
42	## Learning value (be honest; most turns have no moment)
43	- 5: a real fork in their work, or a core concept they need for their goal right now
44	- 4: an important concept that's new to them and just came up
45	- 3: useful but tangential
46	- 2: trivia
47	- 1: noise
48	The app usually only shows moments scoring 4 or 5. Don't inflate scores; don't propose a moment just because you can.
49	
50	## After the learner responds
51	- The app tells you their answer, the verdict, and why. Acknowledge it in one short line at most (the app already showed feedback), then continue the work.
52	- Decide moments: build on the learner's choice. Learning by consequence: if their choice is weak but safe, follow it, let the real results show the effect, then offer to switch. If it would be costly (e.g. wrong conclusions, wasted hours, misleading a stakeholder), explain briefly and ask them to reconsider.
53	- Predict moments: run the code that reveals the answer, then call \`resolve_prediction\` comparing their prediction with the real output, then continue.
54	- If they skipped or deferred, make the call yourself and briefly say why.
55	
56	# Milestones
57	Call \`milestone_reached\` when a meaningful chunk of work completes (for example: data loaded and explored, first model trained, model improved). If it returns boss_due: true, stop immediately and wait: a short boss challenge starts, and you'll get its result before continuing.
58	
59	# Running code
60	- Work in small steps: one focused command per step, concise prints (shapes, key numbers, head of tables), no giant outputs.
61	- Variables may not persist between turns: reload data from files at the start of each script and save intermediate artifacts (e.g. cleaned data) to files.
62	- Charts: use matplotlib, keep them simple and labelled, save each one to a PNG file with savefig (don't call show()), and say in one line what it shows.
63	- Prefer scikit-learn, pandas, and numpy, which are installed. The sandbox has no internet access.
64	- If code fails, fix it quietly and move on; don't narrate every error.
65	
66	# Style
67	Friendly, concise markdown. Short paragraphs or bullets, real numbers, no lectures. Explain only as much as the learner needs to follow the work.`;
68	
69	/** System blocks with a cache breakpoint on the last (only) block. */
70	export const WORK_SYSTEM: Anthropic.Beta.BetaTextBlockParam[] = [
71	  { type: "text", text: WORK_SYSTEM_PROMPT, cache_control: { type: "ephemeral" } },
72	];
 1	/**
 2	 * Dynamic per-turn context (docs/design-plan.md §9.1), sent as a mid-conversation system message right after
 3	 * the turn's user message. Kept in history (append-only), so it is never edited after it is sent.
 4	 */
 5	import type { EngineSummary } from "@/lib/contracts/engine";
 6	import type { Session } from "@/lib/contracts/session";
 7	import { BOSS_MIN_CONCEPTS } from "@/lib/engine/boss";
 8	
 9	const MINUTE = 60_000;
10	
11	export function sessionEndsAt(session: Pick<Session, "createdAt" | "intent">): number {
12	  return session.createdAt + session.intent.minutes * MINUTE;
13	}
14	
15	export function timeLine(session: Pick<Session, "createdAt" | "intent">, now: number): string {
16	  const total = session.intent.minutes * MINUTE;
17	  const elapsed = now - session.createdAt;
18	  const left = Math.max(0, Math.ceil((total - elapsed) / MINUTE));
19	  if (elapsed >= total) return `Time: the planned ${session.intent.minutes} minutes are up. Finish the current step cleanly; the learner may wrap up or keep going.`;
20	  if (elapsed >= 0.8 * total) return `Time: ~2 minutes left: steer toward a milestone.`;
21	  return `Time: about ${left} of ${session.intent.minutes} minutes left.`;
22	}
23	
24	const list = (xs: string[]) => (xs.length ? xs.join(", ") : "none");
25	
26	/** Spaced review across sessions: concepts the engine says are worth revisiting (EngineSummary.dueForReview). */
27	export function reviewLine(concepts: string[]): string {
28	  return `Due for review from earlier sessions: ${concepts.join(", ")}. If the work naturally touches one, a quick practice moment on it is welcome (it counts as review, not first exposure: set first_exposure to false and reuse the exact concept name).`;
29	}
30	
31	export interface ContextInput {
32	  session: Pick<Session, "createdAt" | "intent" | "sketch" | "primer">;
33	  summary: EngineSummary;
34	  now: number;
35	  /** Extra one-off notes for this turn (e.g. how to get the demo dataset). */
36	  notes?: string[];
37	}
38	
39	export function renderContext({ session, summary, now, notes = [] }: ContextInput): string {
40	  const { intent, sketch } = session;
41	  const g = summary.guardrails;
42	  const lines = [
43	    "Co-learn context for this turn (from the app, not the learner):",
44	    `- Learner goal: ${intent.goal}`,
45	    `- Familiarity with this area: ${intent.familiarity}`,
46	    `- ${timeLine(session, now)}`,
47	    `- Moment gate: learning value >= ${summary.valueThreshold}. Target difficulty: ${summary.targetDifficulty.firstExposure} for a new concept, ${summary.targetDifficulty.practice} for practice.`,
48	    `- Guardrails: ${g.enabled ? `on (${g.mode}); fewer interruptions, so only propose your best moments` : "off"}`,
49	    `- Mastered concepts (don't quiz unless due for review): ${list(summary.masteredConcepts)}`,
50	    ...(summary.dueForReview.length ? [`- ${reviewLine(summary.dueForReview)}`] : []),
51	    `- Concepts practised since the last boss: ${list(summary.conceptsSinceBoss)}`,
52	    `- Rolling accuracy: ${summary.rollingAccuracy === null ? "no graded answers yet" : `${Math.round(summary.rollingAccuracy * 100)}%`}`,
53	    `- Recent outcomes: ${summary.recentOutcomes.length ? summary.recentOutcomes.map((o) => `${o.concept} (${o.type}) ${o.score}`).join("; ") : "none"}`,
54	  ];
55	  if (new Set(summary.conceptsSinceBoss).size >= BOSS_MIN_CONCEPTS) {
56	    lines.push("- Enough concepts practised for a boss challenge: call milestone_reached at the next natural checkpoint (e.g. right after you report a result).");
57	  }
58	  if (sketch) {
59	    lines.push(`- Session sketch (a loose guide, not a curriculum): likely milestones: ${list(sketch.milestones)}`);
60	    if (sketch.conceptRadar.length) {
61	      lines.push(
62	        `- Concept radar: ${sketch.conceptRadar.map((c) => `${c.concept} (${c.likelyMomentType}): ${c.whyItMatters}`).join("; ")}`,
63	      );
64	    }
65	  }
66	  if (session.primer) lines.push(`- ${primerLine(session.primer.ideas)}`);
67	  for (const note of notes) lines.push(`- ${note}`);
68	  return lines.join("\n");
69	}
70	
71	export function demoDataNote(hasDemoFile: boolean): string {
72	  return hasDemoFile
73	    ? "Demo dataset: a customer-churn CSV has been uploaded to your sandbox with this message. Find it (e.g. with ls/find) and load it from the file."
74	    : "Demo dataset: no file is attached. First generate a realistic synthetic customer-churn dataset in the sandbox with a fixed seed and save it as churn.csv: ~5,000 rows, ~15% churn, columns customer_id, tenure_months, contract_type, monthly_charges, total_charges (a few missing), support_tickets_90d, payment_method, has_premium_support, last_login_days_ago, plan_tier, cancellation_request_date (mostly filled for churners: a planted leak), churned. Don't point out the leak or the missing values yourself; they're for the learner to discover. Then continue with the task.";
75	}
76	
77	/** The novice primer's bold terms, so Claude builds on what the learner just read instead of re-explaining it. */
78	export function primerLine(ideas: string[]): string {
79	  const terms = ideas.map((i) => /\*\*(.+?)\*\*/.exec(i)?.[1]?.trim()).filter((t): t is string => Boolean(t));
80	  return `The learner was shown a 60-second primer at the start${terms.length ? ` covering: ${terms.join(", ")}` : ""}. Build on it; don't re-explain those basics unless asked.`;
81	}

