 1	/**
 2	 * Tools for the work model: Anthropic's code execution plus our three strict function tools.
 3	 * The input schemas are hand-written to mirror the zod contracts in lib/contracts/moment.ts, because strict
 4	 * tool schemas don't accept length/number/array-size constraints. Zod still validates every input at runtime
 5	 * (with the full constraints), and tools.test.ts keeps the two in sync.
 6	 */
 7	import type Anthropic from "@anthropic-ai/sdk";
 8	import { CODE_EXECUTION_TOOL } from "@/lib/claude/models";
 9	import { MOMENT_TYPES } from "@/lib/contracts/moment";
10	
11	export const LEARNING_MOMENT = "learning_moment";
12	export const RESOLVE_PREDICTION = "resolve_prediction";
13	export const MILESTONE_REACHED = "milestone_reached";
14	
15	type JsonSchema = Record<string, unknown>;
16	
17	const str = (description: string): JsonSchema => ({ type: "string", description });
18	const strArray = (description: string): JsonSchema => ({ type: "array", items: { type: "string" }, description });
19	const obj = (properties: Record<string, JsonSchema>, optional: string[] = []): JsonSchema => ({
20	  type: "object",
21	  properties,
22	  required: Object.keys(properties).filter((k) => !optional.includes(k)),
23	  additionalProperties: false,
24	});
25	
26	export const learningMomentSchema = obj(
27	  {
28	    type: { type: "string", enum: [...MOMENT_TYPES], description: "Moment type (see the guide in the system prompt)." },
29	    concept: str("Short canonical concept name, e.g. \"class imbalance\" (max 60 chars). Reuse the same name for the same concept."),
30	    concept_card: str("Mini lesson shown before the question. Include on first exposure; at most 60 words."),
31	    question: str("One clear question about the learner's actual work, answerable in 1-3 sentences. Never include the answer."),
32	    ideal_answer: str("A model answer (hidden from the learner)."),
33	    rubric: obj(
34	      {
35	        key_points: strArray("1-6 points a good answer must make."),
36	        acceptable_variants: strArray("Other defensible answers (up to 6)."),
37	        misconceptions: strArray("Likely wrong ideas to watch for (up to 6)."),
38	      },
39	      ["acceptable_variants", "misconceptions"],
40	    ),
41	    mc_fallback: obj({
42	      options: strArray("3-4 multiple-choice options, shown only if the learner struggles."),
43	      correct_index: { type: "integer", enum: [0, 1, 2, 3], description: "Index of the best option." },
44	      why: strArray("One short explanation per option, same order and length as options."),
45	    }),
46	    difficulty: { type: "integer", enum: [1, 2, 3, 4, 5], description: "1 (easy) to 5 (hard), aimed at the target difficulty in the turn context." },
47	    first_exposure: { type: "boolean", description: "True if this concept hasn't come up for this learner yet." },
48	    learning_value: { type: "integer", enum: [1, 2, 3, 4, 5], description: "Honest learning value on the 1-5 scale in the system prompt." },
49	    value_reason: str("One line: why this matters for this learner's goal right now."),
50	    costly_mistake: { type: "boolean", description: "True if the learner is about to make a choice with real consequences." },
51	    timing: { type: "string", enum: ["before_step", "after_step"], description: "before_step for decide/predict; after_step for explain_back/spot_issue." },
52	  },
53	  ["concept_card"],
54	);
55	
56	export const resolvePredictionSchema = obj({
57	  moment_id: str("The id of the predict moment, as given in the learner's response."),
58	  actual_result: str("The real result from the code you just ran, in one or two sentences with the key number(s)."),
59	  verdict: { type: "string", enum: ["correct", "partial", "incorrect"], description: "How the learner's prediction compares to the real result." },
60	  why: str("1-2 friendly sentences explaining why the result came out this way."),
61	});
62	
63	export const milestoneSchema = obj({
64	  label: str("Short label for the completed chunk of work, e.g. \"First model trained\"."),
65	  summary: str("What was done and the key real results (metrics), in 1-3 sentences."),
66	  concepts_involved: strArray("Concepts the learner worked with in this chunk (up to 10)."),
67	});
68	
69	const functionTool = (name: string, description: string, schema: JsonSchema): Anthropic.Beta.BetaTool => ({
70	  name,
71	  description,
72	  strict: true,
73	  input_schema: schema as Anthropic.Beta.BetaTool.InputSchema,
74	});
75	
76	/** Stable, deterministic tool list (rendered first in the prompt, so it must never vary between requests). */
77	export const WORK_TOOLS: Anthropic.Beta.BetaToolUnion[] = [
78	  CODE_EXECUTION_TOOL,
79	  functionTool(
80	    LEARNING_MOMENT,
81	    "Pause the work and give the learner a short challenge about what is happening in their work right now. " +
82	      "Call it INSTEAD of continuing when a genuinely valuable learning opportunity comes up. The app may show it " +
83	      "(the turn then ends and waits for the learner) or skip it (you get {status:\"skip\"} and simply keep working). " +
84	      "Never answer the question yourself.",
85	    learningMomentSchema,
86	  ),
87	  functionTool(
88	    RESOLVE_PREDICTION,
89	    "After running the code that reveals the answer to a predict moment, record how the learner's prediction " +
90	      "compared with the real output. The app shows the reveal and awards XP.",
91	    resolvePredictionSchema,
92	  ),
93	  functionTool(
94	    MILESTONE_REACHED,
95	    "Mark that a meaningful chunk of work just completed (e.g. data explored, first model trained, model improved). " +
96	      "If the result says boss_due:true, stop and wait.",
97	    milestoneSchema,
98	  ),
