 1	/**
 2	 * Validates a ChatRequest against stored state before any streaming starts, so failures map to HTTP statuses.
 3	 */
 4	import { z } from "zod";
 5	import type { ChatRequest } from "@/lib/contracts/api";
 6	import type { Session, User } from "@/lib/contracts/session";
 7	import type { Store } from "@/lib/contracts/store";
 8	import { newUser } from "@/lib/store/defaults";
 9	import { isPausedAssistant } from "./blocks";
10	import { BOSS_DECLINED_TEXT, bossResultText, CONTINUE_TEXT, momentResponseText } from "./userText";
11	
12	export { isPausedAssistant } from "./blocks";
13	
14	export const MAX_MESSAGE_CHARS = 4000;
15	
16	const id = z.string().min(1).max(100);
17	export const ChatRequestSchema = z.discriminatedUnion("kind", [
18	  z.object({ sessionId: id, kind: z.literal("message"), text: z.string() }),
19	  z.object({ sessionId: id, kind: z.literal("moment_response"), momentId: id }),
20	  z.object({ sessionId: id, kind: z.literal("boss_result"), bossId: id }),
21	  z.object({ sessionId: id, kind: z.literal("continue") }),
22	  z.object({ sessionId: id, kind: z.literal("boss_declined") }),
23	]);
24	
25	export interface TurnPlan {
26	  anonId: string;
27	  ip: string;
28	  session: Session;
29	  user: User;
30	  request: ChatRequest;
31	  /** Text for Claude's new user turn; null resumes a paused response without a new user turn. */
32	  modelText: string | null;
33	  /** What the learner typed (shown in the transcript), for `message` requests. */
34	  userText?: string;
35	}
36	
37	export type PrepareResult = { ok: true; plan: TurnPlan } | { ok: false; status: number; error: string };
38	
39	const fail = (status: number, error: string): PrepareResult => ({ ok: false, status, error });
40	
41	export async function prepareTurn(store: Store, anonId: string, ip: string, body: unknown): Promise<PrepareResult> {
42	  const parsed = ChatRequestSchema.safeParse(body);
43	  if (!parsed.success) return fail(400, "Invalid request.");
44	  const request = parsed.data;
45	
46	  const session = await store.getSession(request.sessionId);
47	  if (!session || session.anonId !== anonId) return fail(404, "Session not found.");
48	  const user = (await store.getUser(anonId)) ?? newUser(anonId);
49	
50	  const plan = (modelText: string | null, userText?: string): PrepareResult => ({
51	    ok: true,
52	    plan: { anonId, ip, session, user, request, modelText, userText },
53	  });
54	
55	  switch (request.kind) {
56	    case "message": {
57	      const text = request.text.trim();
58	      if (!text) return fail(400, "Message is empty.");
59	      if (text.length > MAX_MESSAGE_CHARS) return fail(400, `Messages are limited to ${MAX_MESSAGE_CHARS} characters.`);
60	      return plan(text, text);
61	    }
62	    case "moment_response": {
63	      const moment = await store.getMoment(session.id, request.momentId);
64	      if (!moment) return fail(404, "Moment not found.");
65	      if (moment.bossId) return fail(400, "Boss questions continue via boss_result.");
66	      const text = momentResponseText(moment);
67	      return text ? plan(text) : fail(409, "This moment hasn't been answered yet.");
68	    }
69	    case "boss_result": {
70	      const boss = await store.getBoss(session.id, request.bossId);
71	      if (!boss) return fail(404, "Boss not found.");
72	      const concepts = await bossConcepts(store, session, boss.id);
73	      const text = bossResultText(boss, concepts);
74	      return text ? plan(text) : fail(409, "This boss challenge isn't finished yet.");
75	    }
76	    case "boss_declined":
77	      if (!session.engine.bossOfferPending) return fail(409, "There's no boss offer to decline.");
78	      return plan(BOSS_DECLINED_TEXT);
79	    case "continue": {
80	      const last = (await store.getApiMessages(session.id)).at(-1);
81	      return plan(isPausedAssistant(last) ? null : CONTINUE_TEXT);
82	    }
83	  }
84	}
85	
86	
87	async function bossConcepts(store: Store, session: Session, bossId: string): Promise<string[]> {
88	  const record = session.engine.bosses.find((b) => b.id === bossId);
89	  if (record?.concepts.length) return record.concepts;
90	  const moments = await store.listMoments(session.id);
91	  return [...new Set(moments.filter((m) => m.bossId === bossId).map((m) => m.candidate.concept))];
92	}

