  1	/**
  2	 * The work turn (design-plan §5): a manual streaming tool loop on the native SDK.
  3	 * Code execution runs server-side; our function tools run here. A shown learning moment or a due boss ends
  4	 * the turn; skipped moments return a tool_result and the loop keeps going within the same turn.
  5	 */
  6	import type Anthropic from "@anthropic-ai/sdk";
  7	import { MODELS } from "@/lib/claude/models";
  8	import { recordSkipped } from "@/lib/engine";
  9	import type { TurnEndReason } from "@/lib/contracts/stream";
 10	import { COMPACTION_BETA, hasCompactionBlock, maybeCompact } from "./compact";
 11	import type { ModelParams, WorkDeps } from "./deps";
 12	import { demoDataNote, renderContext } from "./context";
 13	import { describeError, isAbort, isContainerError, REFUSAL_ERROR, toErrorEvent } from "./errors";
 14	import { handleTool, ToolContext, type PauseReason, type ToolOutcome } from "./handlers";
 15	import type { TurnPlan } from "./prepare";
 16	import { WORK_SYSTEM } from "./prompt";
 17	import { TurnState, type ApiMessage } from "./state";
 18	import { consumeStream, type Emit } from "./stream";
 19	import { WORK_TOOLS } from "./tools";
 20	import { BOSS_DECLINED_TEXT, CONTAINER_RESET_NOTE, skippedPendingNote } from "./userText";
 21	
 22	/** Model requests per user turn (pause_turn re-sends included). */
 23	export const MAX_STEPS = 8;
 24	
 25	export const NOT_RUN = "(not run)";
 26	
 27	const CUT_OFF_TOOL_RESULT = "Your response hit the output limit, so this tool call was cut off and not run. Call it again with a shorter input.";
 28	
 29	export function buildParams(messages: ApiMessage[], containerId: string | undefined): ModelParams {
 30	  const route = MODELS.work;
 31	  return {
 32	    model: route.model,
 33	    max_tokens: route.maxTokens,
 34	    output_config: { effort: route.effort },
 35	    system: WORK_SYSTEM,
 36	    tools: WORK_TOOLS,
 37	    messages,
 38	    // Top-level breakpoint: caches the growing conversation prefix across loop steps and turns.
 39	    cache_control: { type: "ephemeral" },
 40	    ...(containerId ? { container: containerId } : {}),
 41	    // Every request that carries a compaction block must send the compaction beta.
 42	    betas: ["server-side-fallback-2026-07-01", ...(hasCompactionBlock(messages) ? [COMPACTION_BETA] : [])],
 43	    fallbacks: "default",
 44	  };
 45	}
 46	
 47	export async function runTurn(deps: WorkDeps, plan: TurnPlan, emit: Emit, signal: AbortSignal): Promise<void> {
 48	  const { store } = deps;
 49	  const { anonId, ip, session, user } = plan;
 50	  emit({ type: "status", status: "thinking" });
 51	
 52	  const limits = await deps.checkLimits(anonId, ip);
 53	  if (!limits.ok) {
 54	    emit({ type: "error", message: limits.message, retryable: limits.code === "rate_limited", code: limits.code });
 55	    emit({ type: "turn_end", reason: "error", detail: limits.code });
 56	    return;
 57	  }
 58	  // Fail-open: the limits machinery is degraded, so the turn proceeds with a heads-up (not persisted).
 59	  if (limits.warning) emit({ type: "notice", itemId: `notice-limits-${deps.now()}`, text: limits.warning });
 60	
 61	  // Large histories are summarized first (never fails the turn; falls back to the full history). That takes a few
 62	  // seconds, so the learner sees why; "thinking" comes back once it's done.
 63	  let summarized = false;
 64	  const onStart = () => {
 65	    summarized = true;
 66	    emit({ type: "status", status: "summarizing" });
 67	  };
 68	  const history = await maybeCompact({ deps, session, anonId, ip, history: await store.getApiMessages(session.id), signal, onStart });
 69	  if (summarized) emit({ type: "status", status: "thinking" });
 70	  const state = new TurnState(store, session, history);
 71	  const ctx = new ToolContext(deps, state, user);
 72	
 73	  const flush = () => {
 74	    for (const event of ctx.outbox.splice(0)) emit(event);
 75	  };
 76	  const end = async (reason: TurnEndReason) => {
 77	    // Persist before the browser hears about a moment or boss: the grade/boss routes read this state next.
 78	    await state.persist();
 79	    flush();
 80	    emit({ type: "turn_end", reason });
 81	  };
 82	
 83	  try {
 84	    const prefix = joinNotes(await settleBossOffer(ctx, plan), await settlePendingMoment(ctx, plan));
 85	    session.engine = deps.engine.recordWorkTurn(session.engine);
 86	    state.markDirty();
 87	    if (plan.modelText !== null) await addUserTurn(ctx, plan, prefix);
 88	
 89	    let resetTried = false;
 90	    for (let step = 0; ; ) {
 91	      if (step >= MAX_STEPS) return await end("max_steps");
 92	      step++;
 93	
 94	      let started = false;
 95	      let message: Anthropic.Beta.BetaMessage;
 96	      try {
 97	        const stream = deps.startStream(buildParams(state.messages(), session.containerId), signal);
 98	        message = await consumeStream(stream, emit, () => (started = true));
 99	      } catch (err) {
100	        if (started || resetTried || !session.containerId || !isContainerError(err)) throw err;
101	        resetTried = true;
102	        step--;
103	        resetContainer(ctx);
104	        emit({ type: "notice", itemId: `notice:${deps.newId()}`, text: "The coding environment was reset; reloading data." });
105	        continue;
106	      }
107	
108	      await deps.recordUsage(anonId, ip, message.model, message.usage);
109	      if (message.container?.id) session.containerId = message.container.id;
110	
111	      if (message.stop_reason === "refusal") {
112	        // Nothing from a refused response is kept; earlier committed steps stay.
113	        emit(REFUSAL_ERROR);
114	        return await end("refusal");
115	      }
116	
117	      // A code call streamed in a response that stopped for our tool never runs; close its block in the UI.
118	      for (const itemId of state.appendAssistant(message)) emit({ type: "code_result", itemId, stdout: NOT_RUN, stderr: "", returnCode: 0, fileIds: [] });
119	      if (message.stop_reason === "pause_turn") {
120	        state.commit();
121	        continue;
122	      }
123	
124	      const toolUses = message.content.filter((b): b is Anthropic.Beta.BetaToolUseBlock => b.type === "tool_use");
125	      if (toolUses.length === 0) {
126	        state.commit();
127	        return await end("end_turn");
128	      }
129	
130	      const pause = await runTools(ctx, toolUses, message.stop_reason === "max_tokens");
131	      state.commit();
132	      if (pause) return await end(pause);
133	      flush();
134	    }
135	  } catch (err) {
136	    if (signal.aborted || isAbort(err)) return;
137	    console.error("work turn failed:", describeError(err));
138	    await ctx.log("error", { where: "chat", error: describeError(err).slice(0, 200) }).catch(() => {});
139	    // Save committed progress before the client can retry.
140	    await persistQuietly(state);
141	    emit(toErrorEvent(err));
142	    emit({ type: "turn_end", reason: "error" });
143	  } finally {
144	    await persistQuietly(state);
145	  }
146	}
147	
148	async function persistQuietly(state: TurnState): Promise<void> {
149	  if (!state.dirty) return;
150	  await state.persist().catch((e) => console.error("persist failed:", describeError(e)));
151	}
152	
153	/** Runs every tool call of one response and appends all results in a single user message. */
154	async function runTools(ctx: ToolContext, toolUses: Anthropic.Beta.BetaToolUseBlock[], cutOff: boolean): Promise<PauseReason | undefined> {
155	  let pause: PauseReason | undefined;
156	  const results: Anthropic.Beta.BetaToolResultBlockParam[] = [];
157	  for (const block of toolUses) {
158	    const outcome: ToolOutcome = cutOff ? { content: CUT_OFF_TOOL_RESULT, isError: true } : await handleTool(ctx, block);
159	    results.push({ type: "tool_result", tool_use_id: block.id, content: outcome.content, ...(outcome.isError ? { is_error: true } : {}) });
160	    pause ??= outcome.pause;
161	  }
162	  ctx.state.push({ role: "user", content: results });
163	  return pause;
164	}
165	
166	const joinNotes = (...notes: (string | null)[]) => notes.filter(Boolean).join("\n\n") || null;
167	
168	/**
169	 * Clears an open boss offer: "Keep working" (boss_declined) or simply carrying on with a new message both count
170	 * as declining for now. The boss is offered again at the next milestone (Dinakar, 2026-10-18).
171	 */
172	async function settleBossOffer(ctx: ToolContext, plan: TurnPlan): Promise<string | null> {
173	  const { session } = ctx.state;
174	  if (!session.engine.bossOfferPending) return null;
175	  session.engine = { ...session.engine, bossOfferPending: false };
176	  ctx.state.markDirty();
177	  await ctx.log("boss_declined", { via: plan.request.kind });
178	  return plan.request.kind === "boss_declined" ? null : BOSS_DECLINED_TEXT;
179	}
180	
181	/** Clears a pending moment the learner moved past; returns a note for Claude if it was skipped. */
182	async function settlePendingMoment(ctx: ToolContext, plan: TurnPlan): Promise<string | null> {
183	  const { session } = ctx.state;
184	  const pendingId = session.engine.pendingMomentId;
185	  if (!pendingId) return null;
186	  session.engine = recordSkipped(session.engine, pendingId);
187	  ctx.state.markDirty();
188	  if (plan.request.kind === "moment_response" && plan.request.momentId === pendingId) return null;
189	
190	  const moment = await ctx.deps.store.getMoment(session.id, pendingId);
191	  if (moment?.status !== "awaiting_answer") return null;
