   155	async function resolvePrediction(ctx: ToolContext, block: Anthropic.Beta.BetaToolUseBlock): Promise<ToolOutcome> {
   156	  const parsed = ResolvePredictionInputSchema.safeParse(block.input);
   157	  if (!parsed.success) return invalid(parsed.error);
