   173	  const familiarity = state.session.intent.familiarity;
   174	  const mastery = deps.engine.updateMastery(gate.mastery[concept], score, moment.candidate.difficulty, familiarity, now);
   175	  const masteryDelta = mastery.theta - thetaOf(gate.mastery[concept], familiarity);
   176	  await deps.store.putMoment({ ...moment, status: "answered", verdict: input.verdict, why: input.why, xp, answeredAt: now, masteryDelta });
   177	  gate.mastery[concept] = mastery;
   178	  await deps.store.putMastery(ctx.anonId, concept, mastery);
   179	  state.session.engine = deps.engine.recordOutcome(state.session.engine, { momentId: moment.id, concept, type: moment.type, score, at: now });
   180	  await ctx.log("moment_answered", { momentId: moment.id, type: moment.type, concept, verdict: input.verdict, xp, score, help: help ?? null });
   181	
   182	  const itemId = `prediction:${moment.id}`;
   183	  state.addItem({ kind: "prediction_reveal", id: itemId, momentId: moment.id, actualResult: input.actual_result, verdict: input.verdict, why: input.why, xp });
   184	  ctx.outbox.push({ type: "prediction_reveal", itemId, momentId: moment.id, actualResult: input.actual_result, verdict: input.verdict, why: input.why, xp: award });
   185	  return { content: "recorded" };
   186	}
   187	
   188	/** Claude sometimes adds a placeholder milestone (label "x") alongside a learning moment; those aren't shown. */
   189	export const PLACEHOLDER_MILESTONE_RESULT =
   190	  "Ignored, nothing was shown: call milestone_reached only when a meaningful chunk of work has just completed, with a real label and summary.";
   191	
   192	export const BOSS_INSTRUCTION =
   193	  "Stop here and wait: the learner is offered a short boss challenge and chooses whether to take it on. Don't continue the work until you're told what they chose (and the result, if they played).";
   194	
   195	async function milestone(ctx: ToolContext, block: Anthropic.Beta.BetaToolUseBlock): Promise<ToolOutcome> {
   196	  const parsed = MilestoneInputSchema.safeParse(block.input);
   197	  if (!parsed.success) return invalid(parsed.error);
   198	  if (parsed.data.label.trim().length < 3) return { content: PLACEHOLDER_MILESTONE_RESULT };
   199	  const { deps, state } = ctx;
   200	  const engineState = state.session.engine;
   201	  // A moment shown in the same response takes priority; the boss can come at a later milestone.
   202	  const bossesOn = ctx.user.settings.bosses !== false;
   203	  const bossDue = bossesOn && !engineState.pendingMomentId && deps.engine.bossDue(engineState, deps.now(), sessionEndsAt(state.session));
   204	  if (bossDue) {
   205	    // The learner gets a "Take it on / Keep working" offer first; it survives reloads.
   206	    state.session.engine = { ...state.session.engine, bossOfferPending: true };
   207	    state.markDirty();
   208	    await ctx.log("boss_offered", { concepts: state.session.engine.conceptsSinceBoss.length });
   209	  }
   210	  state.addItem({ kind: "milestone", id: block.id, label: parsed.data.label });
   211	  ctx.outbox.push({ type: "milestone", itemId: block.id, label: parsed.data.label, bossDue });
   212	  return bossDue
   213	    ? { content: json({ boss_due: true, instruction: BOSS_INSTRUCTION }), pause: "boss_due" }
   214	    : { content: json({ boss_due: false }) };
   215	}

