78 function WorkspaceBody({ ws, view }: { ws: WorkspaceApi; view: SessionView }) {
79 const router = useRouter();
80 const user = ws.user!;
81 const [drawer, setDrawer] = useState(false);
82 const [keepGoing, setKeepGoing] = useState(false);
83 const now = useNow(5000);
84 const kickedOff = useRef(false);
85
86 // A new session starts working on the learner's goal right away (design-plan §2, step 2).
87 const { send } = ws;
88 useEffect(() => {
89 if (kickedOff.current || view.transcript.length > 0 || view.status !== "active") return;
90 kickedOff.current = true;
91 void send({ sessionId: view.id, kind: "message", text: view.intent.goal });
92 }, [send, view.id, view.intent.goal, view.status, view.transcript.length]);
93
94 useStickToBottom(view, ws.streaming);
95
96 // The level-up toast steps aside on its own after a while (it's a reward, not a task).
97 const { levelUp, dismissLevelUp } = ws;
98 useEffect(() => {
99 if (!levelUp) return;
100 const t = setTimeout(dismissLevelUp, 12_000);
101 return () => clearTimeout(t);
102 }, [levelUp, dismissLevelUp]);
103
104 const pending = openMoment(view);
105 const boss = activeBoss(view);
106 const wrapped = view.status === "wrapped";
107 const busy = ws.streaming || ws.bossState === "loading" || ws.storyWaiting;
108 const timeUp = now !== null && now >= view.endsAt;
109 const showTimePrompt = timeUp && !wrapped && !keepGoing && !busy && !pending && !boss && !view.bossOfferPending && !ws.wrap.data && !ws.wrap.loading;
110 const revealed = revealedPredictions(view);
111
112 const openDrawer = useCallback(() => {
113 setDrawer(true);
114 void ws.loadSessions();
115 }, [ws]);
116
117 const inputPlaceholder = boss
118 ? "Finish or skip the boss challenge above to keep working…"
119 : view.bossOfferPending
120 ? "Or just keep typing to carry on with your work…"
121 : pending
122 ? "Answer the question above, or type to skip it…"
123 : "Message Claude…";
124
125 return (
126 <div className="flex min-h-screen flex-col">
127 <TopBar
128 title={view.title}
129 level={user.level}
130 xpGain={ws.xpGain}
131 endsAt={wrapped ? undefined : view.endsAt}
132 muted={!user.settings.sound}
133 onToggleMute={() => void ws.changeSettings({ sound: !user.settings.sound })}
134 onOpenSettings={openDrawer}
135 codexHref={`/codex?from=/s/${view.id}`}
136 />
137 <LimitsBanner />
138 <SettingsDrawer
139 open={drawer}
140 onClose={() => setDrawer(false)}
141 settings={user.settings}
142 level={user.level.level}
143 unlocks={user.unlocks}
144 onChange={(p) => void ws.changeSettings(p)}
145 sessions={ws.sessions}
146 currentSessionId={view.id}
147 onOpenSession={(id) => {
148 setDrawer(false);
149 if (id !== view.id) router.push(`/s/${id}`);
150 }}
151 onResetData={() => {
152 startOverAsNewUser()
153 .then(() => router.replace("/?start=1"))
154 .catch((err) => window.alert(errorMessage(err)));
155 }}
156 />
157 {ws.levelUp && (
158 <LevelUpToast
159 from={ws.levelUp.from}
160 to={ws.levelUp.to}
161 rewards={ws.levelUp.rewards}
162 onTryTheme={(id) => void ws.changeSettings({ theme: id })}
163 onTrySoundPack={(id) => void ws.changeSettings({ soundPack: id })}
164 onDismiss={ws.dismissLevelUp}
165 />
