305 function TranscriptEntry({
306 item,
307 ws,
308 view,
309 revealed,
310 hideWrapChapter,
311 }: {
312 item: TranscriptItem;
313 ws: WorkspaceApi;
314 view: SessionView;
315 revealed: Set<string>;
316 hideWrapChapter: boolean;
317 }) {
318 const last = view.transcript.at(-1)?.id === item.id;
319 switch (item.kind) {
320 case "user":
321 return <UserMessage text={item.text} />;
322 case "assistant_text":
323 return <AssistantMessage text={item.text} streaming={ws.streaming && last} />;
324 case "code_run":
325 return (
326 <CodeRunBlock
327 sessionId={view.id}
328 language={item.language}
329 code={item.code}
330 stdout={item.stdout}
331 stderr={item.stderr}
332 returnCode={item.returnCode}
333 fileIds={item.fileIds}
334 running={ws.streaming && item.returnCode === undefined}
335 />
336 );
337 case "moment": {
338 const m = view.moments[item.momentId];
339 if (!m) return null;
340 // Once the real run reveals a prediction, the card stays "locked in" and the reveal shows the verdict.
341 const shown = m.type === "predict" && revealed.has(m.id) ? { ...m, status: "awaiting_prediction_result" as const } : m;
342 return (
343 <MomentCard
344 moment={shown}
345 grading={Boolean(ws.grading[m.id])}
346 helpBusy={ws.helpBusy[m.id]}
347 xp={ws.xpByMoment[m.id]}
348 autoFocus={ws.liveIds.has(m.id) && m.status === "awaiting_answer"}
349 {...momentHandlers((a) => void ws.act(m.id, a))}
350 />
351 );
352 }
353 case "prediction_reveal":
354 return (
355 <PredictionReveal
356 prediction={view.moments[item.momentId]?.answer}
357 actualResult={item.actualResult}
358 verdict={item.verdict}
359 why={item.why}
360 xp={item.xp}
361 live={ws.liveIds.has(item.id)}
362 />
363 );
364 case "milestone":
365 return <MilestoneDivider label={item.label} />;
366 case "boss": {
367 const boss = view.bosses[item.bossId];
368 if (!boss) return null;
369 const shownId = bossMomentId(boss, ws.bossShown[boss.id]);
370 const moment = shownId ? view.moments[shownId] : undefined;
371 const next = nextBossQuestion(boss, shownId);
372 return (
373 <div className="space-y-2">
374 <BossCard
375 boss={boss}
376 moment={moment}
377 grading={moment ? Boolean(ws.grading[moment.id]) : false}
378 helpBusy={moment ? ws.helpBusy[moment.id] : undefined}
379 xp={moment ? ws.xpByMoment[moment.id] : undefined}
380 momentHandlers={momentHandlers((a) => moment && void ws.act(moment.id, a))}
381 onSkip={() => void ws.skipBoss(boss.id)}
382 />
383 {next && (
384 <div className="flex justify-end">
385 <Button variant="primary" onClick={() => ws.showBossQuestion(boss.id, next)}>Next question →</Button>
386 </div>
387 )}
388 </div>
389 );
390 }
391 case "story": {
392 const chapter = view.chapters[item.chapterId];
393 if (!chapter || (hideWrapChapter && chapter.trigger === "wrapup")) return null;
394 return <StoryChapterCard chapter={chapter} live={ws.liveIds.has(chapter.id)} />;
395 }
396 case "notice":
397 return <Notice text={item.text} />;
398 }
