401 /** Keeps the newest content in view while the learner is already near the bottom of the page. */
402 function useStickToBottom(view: SessionView, streaming: boolean) {
403 const nearBottom = useRef(true);
404 useEffect(() => {
405 const onScroll = () => {
406 nearBottom.current = window.innerHeight + window.scrollY >= document.body.scrollHeight - 240;
407 };
408 window.addEventListener("scroll", onScroll, { passive: true });
409 return () => window.removeEventListener("scroll", onScroll);
410 }, []);
411 const lastItem = view.transcript.at(-1);
412 const size = view.transcript.length + (lastItem?.kind === "assistant_text" ? lastItem.text.length : 0);
413 useLayoutEffect(() => {
414 if (nearBottom.current) window.scrollTo({ top: document.body.scrollHeight });
415 }, [size, streaming]);
416 }
