 1	/** The gate: code decides whether Claude's candidate moment is shown (design-plan §7.1, principle P8). */
 2	import type { DifficultyKind, GateContext, GateDecision } from "@/lib/contracts/engine";
 3	import type { LearningMomentInput } from "@/lib/contracts/moment";
 4	import { targetDifficulty } from "./difficulty";
 5	import { capsExceeded, valueThreshold } from "./guardrails";
 6	import { isMastered, reviewDue } from "./mastery";
 7	
 8	/** Candidates this far (or further) from the target difficulty are off the challenge band (design-plan §7.1). */
 9	export const OFF_BAND_DISTANCE = 2;
10	
11	/** A top-value moment that prevents a costly mistake may bypass the value threshold and caps. */
12	export function isBreakthrough(c: LearningMomentInput): boolean {
13	  return c.costly_mistake && c.learning_value === 5;
14	}
15	
16	export function gate(candidate: LearningMomentInput, ctx: GateContext): GateDecision {
17	  const { state, mastery, settings, familiarity, now } = ctx;
18	  const breakthrough = isBreakthrough(candidate);
19	  const m = mastery[candidate.concept];
20	
21	  if (state.pendingMomentId !== undefined) return { action: "skip", reason: "one_at_a_time" };
22	
23	  if (candidate.learning_value < valueThreshold(settings) && !breakthrough) {
24	    return { action: "skip", reason: "low_value" };
25	  }
26	
27	  if (isMastered(m) && !reviewDue(m, now)) return { action: "skip", reason: "mastered" };
28	
29	  const kind: DifficultyKind = candidate.first_exposure || !m ? "first_exposure" : "practice";
30	  const target = targetDifficulty(m, kind, familiarity, state.recentOutcomes);
31	  if (Math.abs(candidate.difficulty - target) >= OFF_BAND_DISTANCE) return { action: "skip", reason: "off_band" };
32	
33	  const { enabled, mode } = settings.guardrails;
34	  if (enabled && !breakthrough && capsExceeded(state, mode, now)) {
35	    return mode === "strict" ? { action: "defer", reason: "cap" } : { action: "skip", reason: "cap" };
36	  }
37	
38	  return { action: "show" };
39	}
 1	/** Boss timing and outcome (design-plan §7.4). */
 2	import type { BossOutcome, EngineState } from "@/lib/contracts/engine";
 3	
 4	/** Distinct concepts practised since the last boss before another is due. */
 5	export const BOSS_MIN_CONCEPTS = 3;
 6	/** Minimum gap between boss starts. */
 7	export const BOSS_COOLDOWN_MS = 3 * 60 * 1000;
 8	/** Don't start a boss in the final minute of the session clock (it would run past the end). */
 9	export const BOSS_MIN_REMAINING_MS = 60 * 1000;
10	
11	export function bossDue(state: EngineState, now: number, sessionEndsAt: number): boolean {
12	  if (new Set(state.conceptsSinceBoss).size < BOSS_MIN_CONCEPTS) return false;
13	  if (state.bosses.some((b) => now - b.startedAt < BOSS_COOLDOWN_MS)) return false;
14	  // Past the end the user chose "Keep going" (P7), so bosses are allowed again.
15	  const inFinalMinute = now >= sessionEndsAt - BOSS_MIN_REMAINING_MS && now < sessionEndsAt;
16	  return !inFinalMinute;
17	}
18	
19	/** hits may be fractional (a partial answer is half a hit). */
20	export function bossOutcome(hits: number, maxHits: number): BossOutcome {
21	  if (hits >= maxHits) return "flawless";
22	  if (hits * 2 >= maxHits) return "victory";
23	  return "retreat";
24	}
 1	/** Value thresholds and optional guardrail caps (design-plan §7.2, product-vision "Pacing engine"). */
 2	import type { EngineState, GuardrailMode, UserSettings } from "@/lib/contracts/engine";
 3	
 4	/** Minimum learning_value with guardrails off (the default). */
 5	export const DEFAULT_VALUE_THRESHOLD = 4;
 6	
 7	export const VALUE_THRESHOLD: Record<GuardrailMode, number> = {
 8	  light: 4,
 9	  balanced: 4,
10	  strict: 5, // "only the highest-value moments"
11	};
12	
13	/** Rolling window for per-time caps (design-plan §7.2: "per 10 min"). */
14	export const CAP_WINDOW_MS = 10 * 60 * 1000;
15	
16	export interface Caps {
17	  maxPerWindow?: number; // moments shown within CAP_WINDOW_MS
18	  minTurnsBetween?: number; // work turns since the last shown moment
19	}
20	
21	export const CAPS: Record<GuardrailMode, Caps> = {
22	  light: { minTurnsBetween: 1 },
23	  balanced: { maxPerWindow: 4, minTurnsBetween: 2 },
24	  strict: { maxPerWindow: 2 },
25	};
26	
27	export function valueThreshold(settings: UserSettings): number {
28	  return settings.guardrails.enabled ? VALUE_THRESHOLD[settings.guardrails.mode] : DEFAULT_VALUE_THRESHOLD;
29	}
30	
31	/** Moments shown in the half-open window (now − CAP_WINDOW_MS, now]. */
32	export function momentsInWindow(state: EngineState, now: number): number {
33	  return state.momentsShownAt.filter((t) => t <= now && now - t < CAP_WINDOW_MS).length;
34	}
35	
36	/** True if showing another moment now would break the mode's caps. Turn spacing only applies after a first moment. */
37	export function capsExceeded(state: EngineState, mode: GuardrailMode, now: number): boolean {
38	  const { maxPerWindow, minTurnsBetween } = CAPS[mode];
39	  if (maxPerWindow !== undefined && momentsInWindow(state, now) >= maxPerWindow) return true;
40	  const shownBefore = state.momentsShownAt.length > 0;
41	  return minTurnsBetween !== undefined && shownBefore && state.turnsSinceMoment < minTurnsBetween;
42	}

