  1	/**
  2	 * Pacing-engine contract (Track B implements in lib/engine/, pure + unit-tested).
  3	 * See docs/design-plan.md §7.
  4	 */
  5	import type { HelpLevel, LearningMomentInput, MomentType, Verdict } from "./moment";
  6	
  7	export type Familiarity = "new" | "some" | "comfortable";
  8	export type GuardrailMode = "light" | "balanced" | "strict";
  9	
 10	export interface UserSettings {
 11	  sound: boolean;
 12	  volume: number; // 0..1
 13	  theme: string; // theme id
 14	  soundPack: string; // sound pack id
 15	  guardrails: { enabled: boolean; mode: GuardrailMode };
 16	  /** Boss challenges at milestones (default on). Off: no boss offers at all. */
 17	  bosses?: boolean;
 18	}
 19	
 20	export interface ConceptMastery {
 21	  theta: number;
 22	  n: number;
 23	  lastSeen: number; // epoch ms
 24	  /** Score of the most recent attempt (0..1); drives "Review next time" (struggled last time). */
 25	  lastScore?: number;
 26	}
 27	export type MasteryMap = Record<string, ConceptMastery>;
 28	
 29	export interface Outcome {
 30	  momentId: string;
 31	  concept: string;
 32	  type: MomentType | "boss";
 33	  score: number; // 1 correct, 0.6 correct-after-MC, 0.5 partial, 0 incorrect
 34	  at: number;
 35	}
 36	
 37	/** "skipped": the learner chose "Skip this boss" (no outcome XP, no story chapter). */
 38	export type BossOutcome = "flawless" | "victory" | "retreat" | "skipped";
 39	export interface BossRecord {
 40	  id: string;
 41	  startedAt: number;
 42	  concepts: string[];
 43	  outcome?: BossOutcome;
 44	}
 45	
 46	export interface EngineState {
 47	  pendingMomentId?: string;
 48	  momentsShownAt: number[]; // epoch ms of each shown moment
 49	  turnsSinceMoment: number; // work turns since last shown moment
 50	  conceptsSinceBoss: string[]; // distinct concepts practised since last boss
 51	  bosses: BossRecord[];
 52	  recentOutcomes: Outcome[]; // most recent last, capped (e.g. 20)
 53	  /** A boss is due and the learner hasn't chosen "Take it on" / "Keep working" yet (survives reloads). */
 54	  bossOfferPending?: boolean;
 55	}
 56	
 57	export const initialEngineState = (): EngineState => ({
 58	  momentsShownAt: [],
 59	  turnsSinceMoment: 0,
 60	  conceptsSinceBoss: [],
 61	  bosses: [],
 62	  recentOutcomes: [],
 63	});
 64	
 65	export interface GateContext {
 66	  state: EngineState;
 67	  mastery: MasteryMap;
 68	  settings: UserSettings;
 69	  familiarity: Familiarity;
 70	  now: number;
 71	}
 72	
 73	export type GateDecision =
 74	  | { action: "show" }
 75	  | { action: "defer"; reason: string }
 76	  | { action: "skip"; reason: "one_at_a_time" | "low_value" | "mastered" | "off_band" | "cap" | "unverified" };
 77	
 78	export type DifficultyKind = "first_exposure" | "practice" | "boss";
 79	
 80	/** Engine summary rendered into the work model's dynamic context each turn. */
 81	export interface EngineSummary {
 82	  guardrails: { enabled: boolean; mode: GuardrailMode };
 83	  valueThreshold: number;
 84	  targetDifficulty: { firstExposure: number; practice: number }; // for a typical unseen/seen concept
 85	  masteredConcepts: string[];
 86	  /** Concepts from earlier sessions worth a quick review moment (stale mastered or still shaky), most valuable first, ≤ 3. */
 87	  dueForReview: string[];
 88	  conceptsSinceBoss: string[];
 89	  rollingAccuracy: number | null; // over last 5 graded outcomes
 90	  recentOutcomes: { concept: string; type: string; score: number }[]; // last 3
 91	}
 92	
 93	export type XpEvent =
 94	  | { kind: "answer"; verdict: Verdict; afterMC: boolean; help?: HelpLevel }
 95	  | { kind: "prediction"; verdict: Verdict; help?: HelpLevel }
 96	  | { kind: "boss_hit"; partial: boolean; help?: HelpLevel }
 97	  | { kind: "boss_outcome"; outcome: BossOutcome }
 98	  | { kind: "session_complete" }
 99	  | { kind: "primer_check"; correct: boolean };
100	
101	export interface LevelInfo {
102	  level: number;
103	  xp: number;
104	  levelStartXp: number;
105	  nextLevelXp: number;
106	}
107	
108	export interface LevelReward {
109	  level: number;
110	  kind: "theme" | "sound_pack";
111	  id: string;
112	  label: string;
113	}
114	
115	/** Signatures Track B must export from lib/engine/index.ts. */
116	export interface EngineApi {
117	  gate(candidate: LearningMomentInput, ctx: GateContext): GateDecision;
118	  updateMastery(prev: ConceptMastery | undefined, score: number, difficulty: number, familiarity: Familiarity, now: number): ConceptMastery;
119	  targetDifficulty(m: ConceptMastery | undefined, kind: DifficultyKind, familiarity: Familiarity, recent: Outcome[]): number;
120	  isMastered(m: ConceptMastery | undefined): boolean;
121	  reviewDue(m: ConceptMastery | undefined, now: number): boolean;
122	  bossDue(state: EngineState, now: number, sessionEndsAt: number): boolean;
123	  bossOutcome(hits: number, maxHits: number): BossOutcome;
124	  summarize(ctx: GateContext): EngineSummary;
125	  recordShown(state: EngineState, momentId: string, now: number): EngineState;
126	  recordOutcome(state: EngineState, outcome: Outcome): EngineState;
127	  recordWorkTurn(state: EngineState): EngineState;
128	  xpFor(event: XpEvent): number;
129	  levelFor(totalXp: number): LevelInfo;
130	  rewardsBetween(fromLevel: number, toLevel: number): LevelReward[];
131	}
  1	/**
  2	 * Learning-moment contract: the `learning_moment` tool Claude calls during a work turn,
  3	 * and the client-safe view of a moment. See docs/design-plan.md §6.
  4	 */
  5	import { z } from "zod";
  6	
  7	export const MOMENT_TYPES = ["decide", "predict", "explain_back", "spot_issue", "fill_gap"] as const;
  8	export type MomentType = (typeof MOMENT_TYPES)[number];
  9	
 10	/** Input Claude supplies when it calls the `learning_moment` tool. */
 11	export const LearningMomentInputSchema = z.object({
 12	  type: z.enum(MOMENT_TYPES),
 13	  concept: z.string().min(1).max(60),
 14	  concept_card: z.string().max(600).optional(),
 15	  question: z.string().min(1).max(600),
 16	  ideal_answer: z.string().min(1).max(1200),
 17	  rubric: z.object({
 18	    key_points: z.array(z.string()).min(1).max(6),
 19	    acceptable_variants: z.array(z.string()).max(6).optional(),
