    11	export function recordOutcome(state: EngineState, outcome: Outcome): EngineState {
    12	  return {
    13	    ...state,
    14	    pendingMomentId: state.pendingMomentId === outcome.momentId ? undefined : state.pendingMomentId,
    15	    recentOutcomes: [...state.recentOutcomes, outcome].slice(-RECENT_OUTCOMES_CAP),
    16	    conceptsSinceBoss: state.conceptsSinceBoss.includes(outcome.concept)
    17	      ? [...state.conceptsSinceBoss]
    18	      : [...state.conceptsSinceBoss, outcome.concept],
    19	  };
    20	}
    21	
    22	/** Clears the pending moment without an outcome (learner skipped or deferred it; mastery is not updated). */
    23	export function recordSkipped(state: EngineState, momentId: string): EngineState {
    24	  return { ...state, pendingMomentId: state.pendingMomentId === momentId ? undefined : state.pendingMomentId };
    25	}
    26	
    27	export function recordWorkTurn(state: EngineState): EngineState {
    28	  return { ...state, turnsSinceMoment: state.turnsSinceMoment + 1 };
    29	}
    30	
    31	export function recordBossStarted(state: EngineState, boss: BossRecord): EngineState {
    32	  return { ...state, bosses: [...state.bosses, { ...boss, concepts: [...boss.concepts] }] };
    33	}
    34	
    35	/** Sets the boss outcome and starts a fresh concept count toward the next boss. */
    36	export function recordBossFinished(state: EngineState, bossId: string, outcome: BossOutcome): EngineState {
    37	  return {
    38	    ...state,
    39	    bosses: state.bosses.map((b) => (b.id === bossId ? { ...b, outcome } : b)),
    40	    conceptsSinceBoss: [],
    41	  };
    42	}
     1	/** Engine summary for the work model's dynamic context (design-plan §7.3, §9.1). */
     2	import type { EngineSummary, GateContext } from "@/lib/contracts/engine";
     3	import { rollingAccuracy, targetDifficulty } from "./difficulty";
     4	import { valueThreshold } from "./guardrails";
     5	import { isMastered, reviewDue } from "./mastery";
     6	import { dueForReview } from "./review";
     7	
     8	export const SUMMARY_RECENT_OUTCOMES = 3;
     9	
    10	export function summarize(ctx: GateContext): EngineSummary {
    11	  const { state, mastery, settings, familiarity, now } = ctx;
    12	  const recent = state.recentOutcomes;
    13	  return {
    14	    guardrails: { ...settings.guardrails },
    15	    valueThreshold: valueThreshold(settings),
    16	    targetDifficulty: {
    17	      firstExposure: targetDifficulty(undefined, "first_exposure", familiarity, recent),
    18	      practice: targetDifficulty(undefined, "practice", familiarity, recent),
    19	    },
    20	    // Matches the gate: review-due concepts are left out so Claude may quiz them again.
    21	    masteredConcepts: Object.keys(mastery)
    22	      .filter((c) => isMastered(mastery[c]) && !reviewDue(mastery[c], now))
    23	      .sort(),
    24	    dueForReview: dueForReview(mastery, now),
    25	    conceptsSinceBoss: [...state.conceptsSinceBoss],
    26	    rollingAccuracy: rollingAccuracy(recent),
    27	    recentOutcomes: recent
    28	      .slice(-SUMMARY_RECENT_OUTCOMES)
    29	      .map((o) => ({ concept: o.concept, type: o.type, score: o.score })),
    30	  };
    31	}
