  1	import type { MomentView, Verdict } from "@/lib/contracts/moment";
  2	
  3	/** What a MomentCard shows, derived purely from the server's MomentView plus the client's `grading` flag. */
  4	export type MomentPhase =
  5	  | "question" // free-text answer box
  6	  | "grading" // waiting for /api/moment/grade
  7	  | "choosing" // MC options visible (after "Show options" or a "Not quite")
  8	  | "mc_answered" // option picked: chosen + best option highlighted
  9	  | "answered" // verdict + why + XP
 10	  | "locked_in" // predict: waiting for the real result
 11	  | "revealed" // the learner asked for the answer (after one nudge); shown with no credit
 12	  | "skipped"
 13	  | "deferred"
 14	  | "reported";
 15	
 16	export function momentPhase(m: MomentView, grading = false): MomentPhase {
 17	  if (m.status === "skipped" || m.status === "deferred" || m.status === "reported") return m.status;
 18	  if (m.status === "revealed") return "revealed";
 19	  if (grading) return "grading";
 20	  if (m.status === "awaiting_prediction_result") return "locked_in";
 21	  if (m.mcChoice !== undefined) return "mc_answered";
 22	  if (m.mcOptions?.length && m.verdict !== "correct") return "choosing";
 23	  if (m.verdict) return "answered";
 24	  return "question";
 25	}
 26	
 27	/** A key that changes exactly when new feedback arrives (drives the verdict sound). */
 28	export function feedbackKey(m: MomentView): string | null {
 29	  if (!m.verdict) return null;
 30	  return `${m.id}:${m.verdict}:${m.mcChoice ?? "free"}`;
 31	}
