  1	/** generateBoss (Sonnet, high): 2-3 linked application questions recombining recent concepts and real work details. */
  2	import { z } from "zod";
  3	import type { BossDraft, ContentApi } from "@/lib/contracts/content";
  4	import { LearningMomentInputSchema, type LearningMomentInput } from "@/lib/contracts/moment";
  5	import { MODELS } from "@/lib/claude/models";
  6	import { callStructured } from "./call";
  7	import { ContentShapeError } from "./errors";
  8	import { asData, bullets, DATA_RULE, truncate } from "./prompt";
  9	
 10	const BossQuestionSchema = z.object({
 11	  type: z.enum(["explain_back", "spot_issue", "decide", "predict", "fill_gap"]),
 12	  concept: z.string().describe("Short canonical concept name this question mainly tests"),
 13	  question: z.string().describe("One clear question answerable in 1-3 sentences, using concrete details from the work"),
 14	  ideal_answer: z.string(),
 15	  key_points: z.array(z.string()).describe("1-4 points a good answer covers"),
 16	  acceptable_variants: z.array(z.string()),
 17	  misconceptions: z.array(z.string()),
 18	  mc_options: z.array(z.string()).describe("Exactly 4 options of similar length and detail (the correct one must not stand out as the longest); distractors reflect real misconceptions"),
 19	  mc_correct_index: z.number().int().describe("0-based index of the best option; it must agree with ideal_answer"),
 20	  mc_why: z.array(z.string()).describe("One short explanation per option, same order as mc_options"),
 21	  difficulty: z.number().int().describe("1-5"),
 22	});
 23	
 24	export const BossOutputSchema = z.object({
 25	  name: z.string().describe("Playful boss name tied to the work, e.g. 'The Overfit Bug'"),
 26	  ascii: z.enum(["bug", "slime", "ghost"]),
 27	  intro: z.string().describe("1-2 playful sentences introducing the boss"),
 28	  questions: z.array(BossQuestionSchema).describe("2-3 linked questions"),
 29	});
 30	
 31	export const BOSS_SYSTEM = `You design a short "boss" challenge for Co-learn: a checkpoint after a chunk of real work, where the learner recombines the concepts they just practised.
 32	
 33	Write 2-3 linked application questions:
 34	- Ground them in the learner's actual work: reuse real numbers, column names, and results from the work summary (e.g. "Train recall is 0.98 but test recall is 0.52. What's happening, and what's your first fix?").
 35	- Link them: one scenario that develops across questions (diagnose, then fix, then predict the effect), each combining two or more of the given concepts where possible.
 36	- Application and analysis, not recall of definitions. Each is answerable in 1-3 sentences.
 37	- Aim near the target difficulty (1-5 scale, where the learner should succeed about 70% of the time). If misconceptions are listed, give the learner a fair chance to show they've moved past them.
 38	- Every question needs an ideal answer, a rubric, and a 4-option multiple-choice fallback whose keyed option agrees with the ideal answer, with one short why per option.
 39	
 40	Also give the boss a playful name tied to the work (e.g. "The Overfit Bug", "The Leaky Ghost"), choose an ascii character (bug, slime, or ghost) that fits, and write a 1-2 sentence intro. Keep the tone light and friendly, never threatening.
 41	${DATA_RULE}`;
 42	
 43	type BossInput = Parameters<ContentApi["generateBoss"]>[0];
 44	
 45	export function bossPrompt(input: BossInput): string {
 46	  return [
 47	    asData("learner_goal", truncate(input.intent.goal, 1000)),
 48	    `Learner familiarity: ${input.familiarity}`,
 49	    `Target difficulty: ${input.targetDifficulty}`,
 50	    `Concepts practised since the last boss:\n${bullets(input.concepts)}`,
 51	    `Recent misconceptions or gaps:\n${bullets(input.misconceptions)}`,
 52	    "What was built so far (assistant notes and real code output):",
 53	    asData("work_summary", truncate(input.workSummary, 2500) || "(no details yet)"),
 54	  ].join("\n\n");
 55	}
 56	
 57	/** Maps a raw boss question onto the moment contract, trimming to its limits. Returns null if unusable. */
 58	export function toMomentInput(q: z.infer<typeof BossQuestionSchema>): LearningMomentInput | null {
 59	  const n = Math.min(q.mc_options.length, q.mc_why.length, 4);
 60	  if (n < 3 || q.mc_correct_index < 0 || q.mc_correct_index >= n) return null;
 61	  const draft: LearningMomentInput = {
 62	    type: q.type,
 63	    concept: truncate(q.concept.trim(), 60),
 64	    question: truncate(q.question.trim(), 600),
 65	    ideal_answer: truncate(q.ideal_answer.trim(), 1200),
 66	    rubric: {
 67	      key_points: q.key_points.map((s) => s.trim()).filter(Boolean).slice(0, 6),
 68	      acceptable_variants: q.acceptable_variants.map((s) => s.trim()).filter(Boolean).slice(0, 6),
 69	      misconceptions: q.misconceptions.map((s) => s.trim()).filter(Boolean).slice(0, 6),
 70	    },
 71	    mc_fallback: {
 72	      options: q.mc_options.slice(0, n).map((s) => s.trim()),
 73	      correct_index: q.mc_correct_index,
 74	      why: q.mc_why.slice(0, n).map((s) => s.trim()),
 75	    },
 76	    difficulty: Math.min(5, Math.max(1, Math.round(q.difficulty))),
 77	    first_exposure: false,
 78	    learning_value: 5,
 79	    value_reason: "Boss review: recombines concepts from this chunk of work.",
 80	    costly_mistake: false,
 81	    timing: "after_step",
 82	  };
 83	  if (!draft.rubric.key_points.length) draft.rubric.key_points = [draft.ideal_answer.slice(0, 200)];
 84	  const parsed = LearningMomentInputSchema.safeParse(draft);
 85	  return parsed.success ? parsed.data : null;
 86	}
 87	
 88	export const generateBoss: ContentApi["generateBoss"] = async (input) => {
 89	  const out = await callStructured({ task: "generateBoss", route: MODELS.boss, system: BOSS_SYSTEM, user: bossPrompt(input), schema: BossOutputSchema, timeoutMs: 180_000 });
 90	  return normalizeBoss(out);
 91	};
 92	
 93	export function normalizeBoss(out: z.infer<typeof BossOutputSchema>): BossDraft {
 94	  const questions = out.questions.map(toMomentInput).filter((q): q is LearningMomentInput => q !== null).slice(0, 3);
 95	  if (!questions.length) throw new ContentShapeError("generateBoss", "no usable boss questions");
 96	  return {
 97	    name: truncate(out.name.trim(), 40) || "The Bug",
 98	    ascii: out.ascii,
 99	    intro: truncate(out.intro.trim(), 300),
100	    questions,
101	  };
102	}
