 23	/** Concepts for the boss: practised since the last boss, else the most recent outcomes, else the sketch's radar. */
 24	export function bossConcepts(session: Session): string[] {
 25	  if (session.engine.conceptsSinceBoss.length) return [...new Set(session.engine.conceptsSinceBoss)];
 26	  const recent = distinctRecent(session.engine.recentOutcomes.map((o) => o.concept), 4);
 27	  if (recent.length) return recent;
 28	  return (session.sketch?.conceptRadar ?? []).slice(0, 3).map((c) => c.concept);
 29	}
