 31	/** Keeps verified questions; if verification rejects (or fails on) everything, keeps the originals rather than blocking the boss. */
 32	async function verifiedQuestions(deps: LearningDeps, questions: LearningMomentInput[]): Promise<LearningMomentInput[]> {
 33	  const checks = await Promise.all(
 34	    questions.map((candidate) => deps.content.verifyMoment({ candidate }).catch(() => ({ ok: true as const }))),
 35	  );
 36	  const passed = questions.filter((_, i) => checks[i].ok);
 37	  return passed.length ? passed : questions;
 38	}
