 17	function distinctRecent(values: string[], limit: number): string[] {
 18	  const out: string[] = [];
 19	  for (let i = values.length - 1; i >= 0 && out.length < limit; i--) if (!out.includes(values[i])) out.push(values[i]);
 20	  return out.reverse();
