 1	/** Story bible and chapter generation, persisted as race-safe patches on the session. */
 2	import type { BossOutcome } from "@/lib/contracts/engine";
 3	import type { StoryBible, StoryChapter } from "@/lib/contracts/session";
 4	import { ContentRefusalError } from "@/lib/claude/content/errors";
 5	import type { LearningDeps } from "./deps";
 6	import { appendTranscript, patchSession } from "./sessionStore";
 7	
 8	export async function ensureBible(deps: LearningDeps, sessionId: string): Promise<StoryBible | null> {
 9	  const session = await deps.store.getSession(sessionId);
10	  if (!session) return null;
11	  if (session.story.bible) return session.story.bible;
12	  const bible = await deps.content.generateStoryBible({ intent: session.intent });
13	  const saved = await patchSession(deps, sessionId, (latest) => ({ story: { ...latest.story, bible: latest.story.bible ?? bible } }));
14	  return saved?.story.bible ?? bible;
15	}
16	
17	/** Shown if the story model declines: gentle, generic, and still continues the session's story. */
18	export function fallbackChapter(beat: "boss" | "wrapup", performance?: BossOutcome): Omit<StoryChapter, "id" | "createdAt" | "trigger"> {
19	  const ending =
20	    beat === "wrapup"
21	      ? "As the lanterns dimmed, the crew agreed it had been a good day's journey, and somewhere ahead a new path was already waiting."
22	      : performance === "retreat"
23	        ? "The trouble slipped away into the fog for now. The crew traded a knowing look: next time, they would be ready."
24	        : "With a final clever move the trouble was undone, and a cheer rang out across the deck.";
25	  return {
26	    title: beat === "wrapup" ? "Lanterns at Dusk" : "A Turn in the Tale",
27	    text: `The wind changed, as it always did when something important was about to happen. Our travellers checked their maps, compared notes, and listened to the small voice of experience that had been growing louder all day.\n\n${ending}`,
28	    summary: beat === "wrapup" ? "The crew rested after a day of progress, with a new path ahead." : "The crew faced a challenge and pressed on together.",
29	  };
30	}
31	
32	/**
33	 * Generates and appends the chapter for `trigger` (idempotent per trigger), generating the bible
34	 * first if the background job hasn't produced one yet. Null when the session's mode has no story.
35	 */
36	export async function addChapter(
37	  deps: LearningDeps,
38	  sessionId: string,
39	  trigger: string,
40	  beat: "boss" | "wrapup",
41	  performance?: BossOutcome,
42	): Promise<StoryChapter | null> {
43	  const session = await deps.store.getSession(sessionId);
44	  if (!session?.story.enabled) return null;
45	  const existing = session.story.chapters.find((c) => c.trigger === trigger);
46	  if (existing) return existing;
47	
48	  const bible = await ensureBible(deps, sessionId);
49	  if (!bible) return null;
50	
51	  let draft: Omit<StoryChapter, "id" | "createdAt" | "trigger">;
52	  try {
53	    const previous = session.story.chapters.map(({ title, summary }) => ({ title, summary }));
54	    draft = await deps.content.generateChapter({ bible, previous, trigger, beat, performance });
55	  } catch (err) {
56	    if (!(err instanceof ContentRefusalError)) throw err;
57	    draft = fallbackChapter(beat, performance);
58	  }
59	
60	  const chapter: StoryChapter = { id: deps.newId(), trigger, createdAt: deps.now(), ...draft };
61	  const saved = await patchSession(deps, sessionId, (latest) => ({
62	    story: {
63	      ...latest.story,
64	      chapters: latest.story.chapters.some((c) => c.trigger === trigger) ? latest.story.chapters : [...latest.story.chapters, chapter],
65	    },
66	  }));
67	  const stored = saved?.story.chapters.find((c) => c.trigger === trigger) ?? chapter;
68	  if (stored.id === chapter.id) await appendTranscript(deps, sessionId, { kind: "story", id: `story-${chapter.id}`, chapterId: chapter.id });
69	  return stored;
70	}
 1	/** generateStoryBible (Sonnet): a surprise-genre story lightly themed to the learner's work, from code-picked seeds. */
 2	import { z } from "zod";
 3	import type { Intent, StoryBible } from "@/lib/contracts/session";
 4	import { MODELS } from "@/lib/claude/models";
 5	import { callStructured } from "./call";
 6	import { asData, DATA_RULE, truncate } from "./prompt";
 7	import { pickSeeds, type StorySeeds } from "./seeds";
 8	
 9	export const BibleOutputSchema = z.object({
10	  tone: z.string().describe("A few words, e.g. 'warm, witty, hopeful'"),
11	  setting: z.string().describe("1-2 sentences"),
12	  protagonist: z.string().describe("Name and one-line description"),
13	  motif: z.string().describe("A light, playful echo of the learner's work woven into the world (one sentence)"),
14	  arc: z.array(z.string()).describe("3-4 planned beats; the last resolves at the session wrap-up"),
15	});
16	
17	export const BIBLE_SYSTEM = `You create the story bible for a short serialized reward story. The learner earns chapters by beating challenges while doing real work; each chapter is 150-250 words.
18	Use the given genre, narrator voice, and twist card. Theme the world lightly to the learner's work through a motif (for model training, perhaps a lighthouse that learns to predict storms), but keep it a story, not a lesson.
19	Suitable for all ages: no violence beyond cartoon peril, no romance, no frightening content. Hopeful and playful.
20	${DATA_RULE}`;
21	
22	export function biblePrompt(intent: Intent, seeds: StorySeeds): string {
23	  return [
24	    `Genre: ${seeds.genre}`,
25	    `Narrator voice: ${seeds.narrator}`,
26	    `Twist card (use it somewhere in the arc): ${seeds.twist}`,
27	    "The learner's work, for the motif:",
28	    asData("learner_goal", truncate(intent.goal, 600)),
29	  ].join("\n");
30	}
31	
32	export async function generateStoryBible({ intent }: { intent: Intent }, rng: () => number = Math.random): Promise<StoryBible> {
33	  const seeds = pickSeeds(rng);
34	  const out = await callStructured({ task: "generateStoryBible", route: MODELS.story, system: BIBLE_SYSTEM, user: biblePrompt(intent, seeds), schema: BibleOutputSchema, timeoutMs: 120_000 });
35	  return {
36	    genre: seeds.genre,
37	    tone: out.tone.trim(),
38	    setting: out.setting.trim(),
39	    protagonist: out.protagonist.trim(),
40	    motif: out.motif.trim(),
41	    arc: out.arc.map((b) => b.trim()).filter(Boolean).slice(0, 5),
42	    seeds: { narrator: seeds.narrator, twist: seeds.twist },
43	  };
44	}
 1	/** generateChapter (Sonnet): one 150-250 word chapter, continuous with earlier summaries and shaped by the beat. */
 2	import { z } from "zod";
 3	import type { ContentApi } from "@/lib/contracts/content";
 4	import type { BossOutcome } from "@/lib/contracts/engine";
 5	import { MODELS } from "@/lib/claude/models";
 6	import { callStructured } from "./call";
 7	import { bullets, truncate } from "./prompt";
 8	
 9	export const ChapterOutputSchema = z.object({
10	  title: z.string().describe("Chapter title, at most 8 words"),
11	  text: z.string().describe("The chapter, 150-250 words, in short paragraphs separated by blank lines"),
12	  summary: z.string().describe("1-2 sentence summary for continuity in later chapters"),
13	});
14	
15	export const CHAPTER_SYSTEM = `You write one chapter of a short serialized reward story, following the story bible exactly (genre, narrator voice, tone, protagonist, setting, motif).
16	- 150-250 words, short paragraphs, vivid and concrete. Vary sentence rhythm and avoid stock phrases.
17	- Continue from the previous chapter summaries without contradicting them. Advance the arc by one beat.
18	- Suitable for all ages: cartoon peril at most, kind and hopeful.
19	- Never mention quizzes, XP, scores, or the learner directly. The motif may echo their work lightly.`;
20	
21	const BEAT_GUIDE: Record<BossOutcome | "wrapup", string> = {
22	  flawless: "The heroes win brilliantly: a triumphant, joyful chapter with a moment of earned pride.",
23	  victory: "The heroes win after a real struggle: triumphant and warm.",
24	  retreat: "The challenge slips away for now: end on a hopeful cliffhanger where the heroes regroup and learn something. Never punishing or sad.",
25	  skipped: "The challenge was set aside for another day: a quiet, cozy interlude where the heroes get back to their journey. Never punishing.",
26	  wrapup: "This is the closing chapter for this session: resolve the current thread warmly and leave a small hook for a future adventure.",
27	};
28	
29	type ChapterInput = Parameters<ContentApi["generateChapter"]>[0];
30	
31	export function chapterPrompt(input: ChapterInput): string {
32	  const { bible } = input;
33	  const beat = input.beat === "wrapup" ? BEAT_GUIDE.wrapup : BEAT_GUIDE[input.performance ?? "victory"];
34	  return [
35	    "Story bible:",
36	    `- Genre: ${bible.genre}`,
37	    `- Narrator voice: ${bible.seeds.narrator}`,
38	    `- Tone: ${bible.tone}`,
39	    `- Setting: ${bible.setting}`,
40	    `- Protagonist: ${bible.protagonist}`,
41	    `- Motif: ${bible.motif}`,
42	    `- Twist card: ${bible.seeds.twist}`,
43	    `- Planned arc:\n${bullets(bible.arc.map((b, i) => `${i + 1}. ${b}`))}`,
44	    `Previous chapters (${input.previous.length}):\n${bullets(input.previous.map((c) => `${c.title}: ${c.summary}`))}`,
45	    `This chapter's beat (${input.beat === "boss" ? "a boss challenge just ended" : "session wrap-up"}): ${beat}`,
46	  ].join("\n");
47	}
48	
49	export const generateChapter: ContentApi["generateChapter"] = async (input) => {
50	  const out = await callStructured({ task: "generateChapter", route: MODELS.story, system: CHAPTER_SYSTEM, user: chapterPrompt(input), schema: ChapterOutputSchema, timeoutMs: 120_000 });
51	  return { title: truncate(out.title.trim(), 80), text: out.text.trim(), summary: out.summary.trim() };
52	};
 1	import type { StoryChapter } from "@/lib/contracts/session";
 2	import { defaultDeps, HttpError } from "@/lib/learning/deps";
 3	import { requireCaller } from "@/lib/learning/http";
 4	import { routeErrorResponse } from "@/lib/platform/http";
 5	import { getChapter } from "@/lib/learning/view";
 6	
 7	/** GET /api/story?sessionId=&trigger= → { chapter } (null while it's still generating). */
 8	export async function GET(request: Request) {
 9	  try {
10	    const caller = await requireCaller(request);
11	    const params = new URL(request.url).searchParams;
12	    const sessionId = params.get("sessionId");
13	    const trigger = params.get("trigger");
14	    if (!sessionId || !trigger) throw new HttpError(400, "sessionId and trigger are required");
15	    const chapter: StoryChapter | null = await getChapter(defaultDeps(), caller.anonId, sessionId, trigger);
16	    return Response.json({ chapter });
17	  } catch (err) {
18	    return routeErrorResponse(err, "GET /api/story");
19	  }
20	}

