 1	/** POST /api/wrapup logic: mark wrapped, completion XP (once), codex + suggestions, final chapter. */
 2	import type { WrapUpResponse } from "@/lib/contracts/api";
 3	import type { WrapUpDraft } from "@/lib/contracts/content";
 4	import type { MomentRecord, Session, StoryChapter } from "@/lib/contracts/session";
 5	import { classifyConcepts } from "@/lib/claude/content/wrapup";
 6	import { toMomentView, toUserView } from "@/lib/views";
 7	import type { HandlerResult, LearningDeps } from "./deps";
 8	import { momentScore } from "./scores";
 9	import { loadOwnedSession, patchSession } from "./sessionStore";
10	import { addChapter } from "./story";
11	import { workSummary } from "./workSummary";
12	import { awardXp, loadUser } from "./xp";
13	
14	export function outcomesFrom(moments: MomentRecord[]): { concept: string; type: string; score: number }[] {
15	  return moments.flatMap((m) => {
16	    const score = momentScore(m);
17	    return score === null ? [] : [{ concept: m.candidate.concept, type: m.type, score }];
18	  });
19	}
20	
21	/** Deterministic codex used if the wrap-up model call fails, so wrap-up never dead-ends. */
22	export function fallbackWrapUp(outcomes: ReturnType<typeof outcomesFrom>): WrapUpDraft {
23	  return {
24	    codex: classifyConcepts(outcomes).map((c) => ({
25	      concept: c.concept,
26	      summary: c.result === "strong" ? "You applied this confidently." : c.result === "growing" ? "You're getting there; one more rep will lock it in." : "Worth another look next session.",
27	      result: c.result,
28	    })),
29	    suggestions: ["Pick up where you left off and revisit the concepts marked for review"],
30	  };
31	}
32	
33	export function sessionXp(deps: LearningDeps, session: Session, moments: MomentRecord[]): number {
34	  const momentXp = moments.reduce((sum, m) => sum + (m.xp ?? 0), 0);
35	  const bossXp = session.engine.bosses.reduce((sum, b) => sum + (b.outcome ? deps.engine.xpFor({ kind: "boss_outcome", outcome: b.outcome }) : 0), 0);
36	  return momentXp + bossXp + deps.engine.xpFor({ kind: "session_complete" });
37	}
38	
39	export async function handleWrapUp(deps: LearningDeps, anonId: string, sessionId: string): Promise<HandlerResult<WrapUpResponse>> {
40	  const session = await loadOwnedSession(deps, anonId, sessionId);
41	  const firstWrap = session.status !== "wrapped";
42	  const levelUps: WrapUpResponse["levelUps"] = [];
43	
44	  if (firstWrap) {
45	    await patchSession(deps, sessionId, () => ({ status: "wrapped" }));
46	    const award = await awardXp(deps, anonId, sessionId, [{ kind: "session_complete" }], "Session complete");
47	    if (award?.levelUp) levelUps.push(award.levelUp);
48	  }
49	
50	  const [moments, transcript] = await Promise.all([deps.store.listMoments(sessionId), deps.store.getTranscript(sessionId)]);
51	  const outcomes = outcomesFrom(moments);
52	
53	  const [draft, chapter] = await Promise.all([
54	    deps.content
55	      .generateWrapUp({ intent: session.intent, outcomes, workSummary: workSummary(transcript, 2000) })
56	      .catch(() => fallbackWrapUp(outcomes)),
57	    addChapter(deps, sessionId, "wrapup", "wrapup").catch((): StoryChapter | null => null),
58	  ]);
59	
60	  const latest = (await deps.store.getSession(sessionId)) ?? session;
61	  if (firstWrap) {
62	    await deps.store.logEvent({ at: deps.now(), anonId, sessionId, name: "session_wrapped", props: { moments: moments.length, answered: outcomes.length } });
63	  }
64	
65	  return {
66	    body: {
67	      deferred: (await asWrapUpQuestions(deps, moments.filter((m) => m.status === "deferred"))).map(toMomentView),
68	      codex: draft.codex,
69	      sessionXp: sessionXp(deps, latest, moments),
70	      user: toUserView(await loadUser(deps, anonId)),
71	      chapter: chapter ?? undefined,
72	      suggestions: draft.suggestions,
73	      levelUps,
74	    },
75	    background: [],
76	  };
77	}
78	
79	/**
80	 * A saved *predict* question can't be graded against "the next run" anymore (the work moved on), so at wrap-up
 1	/** generateWrapUp (Sonnet): codex lines + "next time you could…" suggestions. Results are classified in code from scores. */
 2	import { z } from "zod";
 3	import type { ContentApi, WrapUpDraft } from "@/lib/contracts/content";
 4	import { MODELS } from "@/lib/claude/models";
 5	import { callStructured } from "./call";
 6	import { asData, bullets, DATA_RULE, truncate } from "./prompt";
 7	
 8	export const WrapUpOutputSchema = z.object({
 9	  codex: z.array(
10	    z.object({
11	      concept: z.string().describe("Concept name exactly as given"),
12	      summary: z.string().describe("One line (at most 20 words): the takeaway, tied to their work"),
13	    }),
14	  ),
15	  suggestions: z.array(z.string()).describe("2-3 concrete next tasks, imperative, without a 'Next time you could' prefix"),
16	});
17	
18	export const WRAPUP_SYSTEM = `You write the wrap-up for a Co-learn session, where a professional did real work with Claude and practised concepts along the way.
19	- codex: one entry per concept given, in the same order, with a one-line takeaway (at most 20 words) tied to what they actually did. Plain words, no jargon beyond the concept itself.
20	- suggestions: 2-3 concrete next steps, each a short task the learner could start as their next session (imperative, e.g. "Pick a decision threshold from real offer costs"), building on their work and on the concepts that still need practice. The UI shows them under the heading "Next time you could…", so don't start with that phrase.
21	Warm and specific; never grade or scold.
22	${DATA_RULE}`;
23	
24	type Outcome = { concept: string; type: string; score: number };
25	export type CodexResult = WrapUpDraft["codex"][number]["result"];
26	
27	/** Average score per concept → strong (≥ 0.8), growing (≥ 0.5), or review. */
28	export function classifyConcepts(outcomes: Outcome[]): { concept: string; avg: number; result: CodexResult }[] {
29	  const byConcept = new Map<string, number[]>();
30	  for (const o of outcomes) byConcept.set(o.concept, [...(byConcept.get(o.concept) ?? []), o.score]);
31	  return [...byConcept.entries()].map(([concept, scores]) => {
32	    const avg = scores.reduce((a, b) => a + b, 0) / scores.length;
33	    return { concept, avg, result: avg >= 0.8 ? "strong" : avg >= 0.5 ? "growing" : "review" };
34	  });
35	}
36	
37	type WrapUpInput = Parameters<ContentApi["generateWrapUp"]>[0];
38	
39	export function wrapUpPrompt(input: WrapUpInput, classified: ReturnType<typeof classifyConcepts>): string {
40	  return [
41	    asData("learner_goal", truncate(input.intent.goal, 1000)),
42	    `Concepts practised (average score 0-1, result):\n${bullets(classified.map((c) => `${c.concept}: ${c.avg.toFixed(2)}, ${c.result}`))}`,
43	    "What they built:",
44	    asData("work_summary", truncate(input.workSummary, 2500) || "(no details)"),
45	  ].join("\n\n");
46	}
47	
48	export const generateWrapUp: ContentApi["generateWrapUp"] = async (input) => {
49	  const classified = classifyConcepts(input.outcomes);
50	  const out = await callStructured({ task: "generateWrapUp", route: MODELS.wrapup, system: WRAPUP_SYSTEM, user: wrapUpPrompt(input, classified), schema: WrapUpOutputSchema, timeoutMs: 120_000 });
51	  const summaries = new Map(out.codex.map((c) => [c.concept.trim().toLowerCase(), c.summary.trim()]));
52	  return {
53	    codex: classified.map((c, i) => ({
54	      concept: c.concept,
55	      summary: summaries.get(c.concept.toLowerCase()) ?? out.codex[i]?.summary.trim() ?? "",
56	      result: c.result,
57	    })),
58	    suggestions: out.suggestions.map(stripLeadIn).filter(Boolean).slice(0, 3),
59	  };
60	};
61	
62	/** "Next time you could pick a threshold…" → "Pick a threshold…" (the UI already shows the lead-in). */
63	export function stripLeadIn(suggestion: string): string {
64	  const rest = suggestion.trim().replace(/^next time,?\s+you could\s+/i, "").replace(/[….]+$/, "").trim();
65	  return rest ? rest[0].toUpperCase() + rest.slice(1) : "";
66	}

