 1	/**
 2	 * The cross-session Codex: everything the learner has practised, from their per-user mastery map.
 3	 * Served by GET /api/codex; rendered by app/codex. Status rules live in the engine (lib/engine/review.ts).
 4	 */
 5	import type { MasteryMap } from "@/lib/contracts/engine";
 6	import { conceptStatus, strength, type ConceptStatus } from "@/lib/engine";
 7	
 8	export type CodexStatus = ConceptStatus;
 9	
10	export interface CodexEntry {
11	  concept: string;
12	  /** P(correct on a medium, difficulty-3 question), 0..1. */
13	  strength: number;
14	  /** Graded attempts. */
15	  n: number;
16	  /** Epoch ms of the last graded attempt. */
17	  lastSeen: number;
18	  status: CodexStatus;
19	}
20	
21	export interface CodexResponse {
22	  concepts: CodexEntry[];
23	}
24	
25	/** Display order: celebrate what's mastered first, then what's growing, then what to review next time. */
26	export const CODEX_STATUS_ORDER: CodexStatus[] = ["mastered", "growing", "review"];
27	
28	/** Every concept in the map, grouped by status (CODEX_STATUS_ORDER), most recently practised first, then by name. */
29	export function buildCodex(mastery: MasteryMap, now: number): CodexEntry[] {
30	  return Object.entries(mastery)
31	    .filter(([, m]) => m.n > 0)
32	    .map(([concept, m]) => ({
33	      concept,
34	      strength: Math.round(strength(m) * 1000) / 1000,
35	      n: m.n,
36	      lastSeen: m.lastSeen,
37	      status: conceptStatus(m, now),
38	    }))
39	    .sort(
40	      (a, b) =>
41	        CODEX_STATUS_ORDER.indexOf(a.status) - CODEX_STATUS_ORDER.indexOf(b.status) ||
42	        b.lastSeen - a.lastSeen ||
43	        a.concept.localeCompare(b.concept),
44	    );
45	}
 1	"use client";
 2	
 3	import Link from "next/link";
 4	import { useSearchParams } from "next/navigation";
 5	import { useEffect, useState } from "react";
 6	import { CodexList } from "@/components/CodexList";
 7	import { Button, Spinner, focusRing } from "@/components/ui";
 8	import type { CodexEntry, CodexResponse } from "@/lib/codex";
 9	import { ApiError, apiGet, errorMessage } from "@/lib/client/api";
10	
11	type Load = { kind: "loading" } | { kind: "error"; message: string; signedOut: boolean } | { kind: "ready"; concepts: CodexEntry[]; now: number };
12	
13	/** Only same-origin app paths are allowed as the back target (no "//host" or "/\host" open redirects). */
14	export function safeBackHref(from: string | null): string {
15	  return from && /^\/(?![/\\])/.test(from) ? from : "/";
16	}
17	
18	export function CodexView() {
19	  const backHref = safeBackHref(useSearchParams().get("from"));
20	  const [load, setLoad] = useState<Load>({ kind: "loading" });
21	  const [attempt, setAttempt] = useState(0); // bumped by "Try again"
22	
23	  useEffect(() => {
24	    const ctrl = new AbortController();
25	    apiGet<CodexResponse>("/api/codex", ctrl.signal)
26	      .then((res) => setLoad({ kind: "ready", concepts: res.concepts, now: Date.now() }))
27	      .catch((err) => {
28	        if (!ctrl.signal.aborted) setLoad({ kind: "error", message: errorMessage(err), signedOut: err instanceof ApiError && err.status === 401 });
29	      });
30	    return () => ctrl.abort();
31	  }, [attempt]);
32	
33	  const mastered = load.kind === "ready" ? load.concepts.filter((c) => c.status === "mastered").length : 0;
34	
35	  return (
36	    <main className="mx-auto w-full max-w-[720px] flex-1 px-4 pt-6 pb-12">
37	      <Link href={backHref} className={`inline-flex items-center gap-1 rounded-full px-1 py-1 text-sm text-muted hover:text-text ${focusRing}`}>
38	        <span aria-hidden="true">←</span> {backHref.startsWith("/s/") ? "Back to your session" : "Back"}
39	      </Link>
40	      <header className="mt-4 mb-6 px-1">
41	        <h1 className="text-2xl font-extrabold">Codex</h1>
42	        <p className="text-muted">
43	          Everything you&apos;ve practised with Co-learn, across sessions.
44	          {load.kind === "ready" && load.concepts.length > 0 && (
45	            <> {load.concepts.length} {load.concepts.length === 1 ? "concept" : "concepts"} so far, {mastered} mastered.</>
46	          )}
47	        </p>
48	      </header>
49	
50	      <div>
51	        {load.kind === "loading" && (
52	          <div className="flex justify-center py-12">
53	            <Spinner label="Loading your Codex" />
54	          </div>
55	        )}
56	        {load.kind === "error" && (
57	          <div className="flex flex-col items-center gap-3 py-12 text-center">
58	            <p role="status" className="text-muted">{load.message}</p>
59	            {load.signedOut ? (
60	              <Link href="/" className={`rounded-full bg-primary px-5 py-2.5 font-semibold text-primary-foreground shadow-soft ${focusRing}`}>
61	                Go to start
62	              </Link>
63	            ) : (
64	              <Button
65	                size="sm"
66	                onClick={() => {
67	                  setLoad({ kind: "loading" });
68	                  setAttempt((n) => n + 1);
69	                }}
70	              >
71	                Try again
72	              </Button>
73	            )}
74	          </div>
75	        )}
76	        {load.kind === "ready" && <CodexList concepts={load.concepts} now={load.now} />}
77	      </div>
78	    </main>
79	  );
80	}

