 1	import Link from "next/link";
 2	import { CODEX_STATUS_ORDER, type CodexEntry, type CodexStatus } from "@/lib/codex";
 3	import { timeAgo } from "@/lib/ui/relativeTime";
 4	import { Card, focusRing } from "./ui";
 5	
 6	/** Section copy per status. Encouraging throughout (P2): "review next time", never "weak". */
 7	export const CODEX_SECTION: Record<CodexStatus, { title: string; blurb: string }> = {
 8	  mastered: { title: "Mastered", blurb: "Solid. They'll pop up for a quick check now and then, so they stay that way." },
 9	  growing: { title: "Growing", blurb: "Getting stronger with each practice." },
10	  review: { title: "Review next time", blurb: "Worth another look. Co-learn brings these back when your work touches them." },
11	};
12	
13	const attempts = (n: number) => `${n} ${n === 1 ? "attempt" : "attempts"}`;
14	
15	/** The cross-session Codex, grouped by status. `now` is fixed by the caller so times don't drift between renders. */
16	export function CodexList({ concepts, now }: { concepts: CodexEntry[]; now: number }) {
17	  if (concepts.length === 0) {
18	    return (
19	      <Card className="text-center">
20	        <p className="text-muted">Your Codex fills up as you learn. Start a session to add your first concept.</p>
21	        <Link
22	          href="/"
23	          className={`mt-4 inline-flex rounded-full bg-primary px-5 py-2.5 font-semibold text-primary-foreground shadow-soft hover:brightness-110 ${focusRing}`}
24	        >
25	          Start a session
26	        </Link>
27	      </Card>
28	    );
29	  }
30	
31	  return (
32	    <div className="space-y-6">
33	      {CODEX_STATUS_ORDER.map((status) => {
34	        const group = concepts.filter((c) => c.status === status);
35	        if (group.length === 0) return null;
36	        const { title, blurb } = CODEX_SECTION[status];
37	        const headingId = `codex-${status}`;
38	        return (
39	          <section key={status} aria-labelledby={headingId}>
40	            <div className="mb-2 px-1">
41	              <h2 id={headingId} className="text-lg font-extrabold">
42	                {title} <span className="text-sm font-semibold text-muted">· {group.length}</span>
43	              </h2>
44	              <p className="text-sm text-muted">{blurb}</p>
45	            </div>
46	            <ul className="divide-y divide-border rounded-card border border-border bg-surface shadow-soft">
47	              {group.map((c) => (
48	                <CodexRow key={c.concept} entry={c} now={now} />
49	              ))}
50	            </ul>
51	          </section>
52	        );
53	      })}
54	    </div>
55	  );
56	}
57	
58	function CodexRow({ entry, now }: { entry: CodexEntry; now: number }) {
59	  const pct = Math.round(entry.strength * 100);
60	  return (
61	    <li className="px-5 py-4 sm:px-6">
62	      <div className="flex items-baseline justify-between gap-3">
63	        <p className="min-w-0 font-bold break-words">{entry.concept}</p>
64	        <p className="shrink-0 text-xs text-muted">
65	          {attempts(entry.n)} · last practised {timeAgo(entry.lastSeen, now)}
66	        </p>
67	      </div>
68	      <div
69	        role="meter"
70	        aria-label={`Strength: ${entry.concept}`}
71	        aria-valuemin={0}
72	        aria-valuemax={100}
73	        aria-valuenow={pct}
74	        aria-valuetext={`${pct}%`}
75	        className="mt-2 h-2 overflow-hidden rounded-full bg-surface-2"
76	      >
77	        <div className="h-full rounded-full bg-accent" style={{ width: `${Math.max(pct, 4)}%` }} />
78	      </div>
79	    </li>
80	  );

