     1	/**
     2	 * Content-generation contract (Track D implements in lib/claude/content/*).
     3	 * Each function makes one structured Claude call (messages.parse + zodOutputFormat).
     4	 */
     5	import type { LearningMomentInput, Verdict } from "./moment";
     6	import type { Intent, Primer, SessionSketch, StoryBible, StoryChapter } from "./session";
     7	import type { BossOutcome, Familiarity } from "./engine";
     8	
     9	export interface GradeResult {
    10	  verdict: Verdict;
    11	  why: string; // 1-2 sentences, encouraging, explains the reasoning (P3)
    12	  missingPoints: string[];
    13	  misconception?: string;
    14	}
    15	
    16	export interface VerifyResult {
    17	  ok: boolean; // false → gate converts to skip("unverified")
    18	  reason?: string;
    19	}
    20	
    21	export interface BossDraft {
    22	  name: string;
    23	  ascii: "bug" | "slime" | "ghost";
    24	  intro: string; // 1-2 playful sentences
    25	  questions: LearningMomentInput[]; // 2-3 linked questions, type "explain_back"/"spot_issue"/"decide" shapes reused
    26	}
    27	
    28	export interface WrapUpDraft {
    29	  codex: { concept: string; summary: string; result: "strong" | "growing" | "review" }[];
    30	  suggestions: string[]; // 2-3 "next time you could..." ideas
    31	}
    32	
    33	/** What the help tools know about one question (the answer key stays server-side). */
    34	export interface HelpContext {
